import { EditorAction } from "./editor-controls";
import { DEMO_ASSETS, DEMO_PROJECT } from "./editor-demo";
import { propertyDefaults, type InspectorTarget, type PropertyKey, type PropertyValues } from "./editor-property-model";
import styles from "./editor.module.css";

// 样板入口是公开samples页的一部分，不是测试专用的任意状态注入后门。
// 所有数值操作经过正式字段的同一草稿、精度和范围校验。
// 样板只提供一个局部覆盖值存放处，便于验证确认后的显示和多选传播。
// 不调用FFmpeg、不改原文件、不把参数写入正式工程的片段对象。
// 因此截图可以证明属性UI交互，不能作为真实画面缩放或声音淡入的证明。
// 两列分别调用InspectorSample，各自创建state，不共用一个提升到父层的对象。
// DEMO_ASSETS本身只读使用，更新时产生新target和values，不原地改静态资源。
// B可以作为A修改的反证，而不是再画一张没有真实状态的对照图。
// 样板按钮负责提供选择条件，正式检查器仍负责判断哪些属性有效。
// 不在按钮处理中预先过滤字段，否则会掩盖检查器交集算法错误。

// 每个实例各有覆盖值和类型选择，不借用正式片段数组或全局选择store。
// 两项视频故意使用不同缩放，能够验证“混合”而不是重复同一个默认值。
// 图片安排长度取演示片段十秒，不把图片源不存在的duration编成探测时长。
function sampleTargets(): InspectorTarget[] {
  // sampleTargets作为useState惰性初始化器使用，打字重渲染不重新创建初始集合。
  // 否则每次确认数字都会把上一字段覆盖还原成初始值，无法测试多字段累积编辑。
  // index===1只控制预设的混合条件，不作为后续提交目标的业务身份。
  // 后续更新始终使用ids.includes，数组顺序不构成编辑哪个对象的依据。
  // 目标duration无单位字符串，数值字段统一在显示层附加秒单位。
  // 没有值的默认字段不提前写成字符串，mixed比较仍是数值比较。
  // 这里的id可以借用素材ID，因为样板每个素材只构造一个目标。
  // 正式工程同源多实例必须用片段ID，不能照搬这个一对一数据关系。
  // 第一视频缩放默认100，第二视频覆盖为80，故意构成一个可观察混合值。
  // 不把两项都设80再声称覆盖了混合提交，那样无法发现代表值跳过回调的错误。
  // 图片安排十秒，是演示工程中的展示长度，不是探测结果或图片元数据。
  // 音频和视频已有duration沿用原演示事实，不能按文件名字数捏造时长。
  // 每次实例初始化都返回新数组，A改values不会通过共享对象引用影响B。
  // 默认值仍由propertyDefaults读取，这里不复制960/540等项目中心常量。
  // 初始覆盖只用于明确测试条件，正式会话绝不引用本函数建立工程。
  return DEMO_ASSETS.map((asset, index) => ({ id: asset.id, asset, duration: asset.duration ?? 10, values: index === 1 ? { scale: 80 } : {} }));
}

// 更新只针对所选ID，未选对象的覆盖值与默认来源都保留。
// 重置逐个写入当前项目默认值，不填一个固定960，也不沿用别的目标安排长度。
// 这里没有保存、媒体处理或成功通知，状态随样板卸载释放。
function InspectorSample({ id }: { id: string }) {
  // targets是已经确认的样板状态，ids只是当前查看的目标集合。
  // 改选择不清除targets，因此切回原对象仍能读到之前确认的80。
  // 草稿属于字段组件，切对象时通过目标key释放，未确认文本不会变成覆盖值。
  // 当前selected从稳定ID过滤，不用按钮下标直接保存当前对象引用。
  // 对象更新后引用会变化，按ID重新查找才能拿到最新确认值。
  // A/B的id仅用于界面和回归作用域，不作为全局缓存键或跨实例数据仓库。
  const { t } = useTranslation();
  const [targets, setTargets] = useState(sampleTargets), [ids, setIds] = useState<string[]>([DEMO_ASSETS[0].id]);
  const selected = targets.filter(target => ids.includes(target.id));
  // ids保存多个稳定身份，targets更新后selected立即读到新的values。
  // 不把selected本身存为state，避免值更新后仍持有旧对象引用。
  // ids为空时selected真为空，兼容接口不会给样板补上默认scene_02。
  // 三类组合可能没有公共字段，仍将完整集合传下去，让外壳说明数量与空交集。
  // 组重置更新targets但不改ids，选择集合不会因为恢复数值而自动跳成单选。
  // targets和ids都属于当前InspectorSample，A的setTargets拿不到B的setter。
  // 这比在组件外保存一个“上次参数”对象更可靠，后者会在两列间串值。
  // 样板不订阅正式timeline，也不会以真实素材导入数量初始化演示选择。
  function commit(key: PropertyKey, value: number) {
    // 一次字段提交作用于当前全部选择，多选代表值相同也不能跳过其他对象。
    // 例如首项已是80、另一项100，输入80应把后者也更新到80。
    // 保留未选target的原引用，避免一次输入重置整个样板。
    // values用对象合并保留其他已经确认字段，改X不能把缩放清回默认。
    // 接口只收一个字段键，不接任意JSON对象来绕过字段范围。
    // value已通过公共输入的有限数字校验，这里不再进行不同的取整或夹限。
    // 不在提交后显示“效果生效”，因为当前没有真实媒体效果处理。
    // 切到别的类型后旧目标的确认值仍在，这属于样板内状态，不是项目保存。
    setTargets(current => current.map(target => ids.includes(target.id) ? { ...target, values: { ...target.values, [key]: value } } : target));
  }
  function reset(keys: PropertyKey[]) {
    // 每个选中对象单独计算默认值，尤其duration可能因对象安排长度而不同。
    // 不能只计算第一个对象的默认值，再给所有对象写同一时长。
    // 未选对象直接保留，因此A重置两个视频不会清掉图片已确认的参数。
    // keys来自当前分组，重置变换不会触碰淡入或音量。
    // 对部分覆盖保留其他键，避免重置一组等于清空整张属性表。
    // 这里明确写入默认数值，不声称执行了删除工程效果节点或重建视频文件。
    // 重置后字段局部草稿由InspectorSection的epoch重新初始化。
    // 即使默认值与旧确认值相等，也不会留下用户尚未确认的非法文本。
    setTargets(current => current.map(target => {
      if (!ids.includes(target.id)) return target;
      const values: Partial<PropertyValues> = { ...target.values }, defaults = propertyDefaults(target, DEMO_PROJECT);
      for (const key of keys) values[key] = defaults[key];
      return { ...target, values };
    }));
  }
  return <section data-inspector-sample={id} className={`${styles.sampleInstance} ${styles.inspectorSample}`}><h2>{t("toolBox.editorUi.inspectorSamples")} {id}</h2><div className={styles.sampleActions}>
    {/* 单个目标按钮只变更样板选择；正式页不会显示这些演示选择器。 */}
    {/* pressed只用于单选，不能把多选中的第一个按钮误标成唯一选中目标。 */}
    {targets.map(target => <EditorAction key={target.id} label={target.asset.name} pressed={ids.length === 1 && ids[0] === target.id} onClick={() => setIds([target.id])} />)}
    <EditorAction label={t("toolBox.editorUi.noneSelected")} onClick={() => setIds([])} /><EditorAction label={t("toolBox.editorUi.mixedSelection")} onClick={() => setIds(targets.slice(0, 2).map(target => target.id))} />
    {/* 混合类型直接给同一个检查器传目标交集，不另造多选专用表单。 */}
    {/* 索引只描述此处固定演示组合，真正传给检查器的仍是稳定目标ID。 */}
    {/* 视频加图片检验共同变换，视频加音频检验共同淡入淡出。 */}
    {/* 图片加音频和三类组合检验空交集，不把第一项字段当成多选字段。 */}
    {/* 组合标签使用现有类型翻译，加入英文后无需再维护一套组合词条。 */}
    {/* 控件允许自然换行，样板窄列不会把按钮缩成难以点击的小块。 */}
    {([[0, 2], [0, 3], [2, 3], [0, 2, 3]] as const).map(indices => <span key={indices.join("-")} data-inspector-selection={indices.join("-")}><EditorAction label={indices.map(index => t(`toolBox.editorUi.${targets[index].asset.kind}`)).join(" + ")} onClick={() => setIds(indices.map(index => targets[index].id))} /></span>)}
  </div><ClipInspector targets={selected} project={DEMO_PROJECT} onCommit={commit} onReset={reset} /></section>;
}

// A/B共用组件但分别执行hook；操作A不应改变B的值、草稿、错误或折叠状态。
// 样板放在已有samples入口，正式工作区不会出现练习用类型切换按钮。
export function EditorInspectorSamples() {
  // 两实例并排只是样板布局；窄容器可变成纵向，不改变两份状态生命周期。
  // 无论排列方向如何，data-inspector-sample身份不变，断言不会因排序读错列。
  // 相同静态封面可共享资源地址，但确认值与展开状态不能共享。
  // 本入口不产生播放器，因此更改位置只显示确认数字，不伪造画布跟随效果。
  // 若未来真实效果接入，样板仍保留为表单状态回归，不能替代实机媒体验证。
  // 父层只排版两个实例，不持有共享选择或共享reset计数。
  // 对两个实例使用同一组件，才能发现公共字段修改是否导致状态互相污染。
  // B不会订阅A的提交回调；测试必须分别读取两列确认值而非只看按钮变色。
  // 样板卸载后局部状态自然释放，返回正式工作区不会带入练习值。
  // 不读取用户素材或已有工程，回归可反复运行且不会改动本地作品。
  return <div className={styles.sampleGrid}><InspectorSample id="A" /><InspectorSample id="B" /></div>;
}

"use client";

// 属性外壳、分组和数值字段是正式工作区与样板的同一实现。
// 这里组合展示模型，媒体效果、工程提交与持久化均由外部决定。
import { RotateCcw } from "lucide-react";
import { useState } from "react";
import { useTranslation, t } from "@/i18n";
import { EditorAction, EditorFloatField, EditorGroup, EditorPlaceholder } from "./editor-controls";
import type { EditorMediaAsset, EditorPreviewProject } from "./editor-panels";
import { DEMO_ASSETS, DEMO_CLIPS, DEMO_PROJECT } from "./editor-demo";
import { inspectorFields, propertyGroup, propertyValue, type InspectorTarget, type PropertyField, type PropertyKey } from "./editor-property-model";
import styles from "./editor.module.css";

// 检查器像一张按对象类型裁剪的表单，不是素材浏览器的第二个详情页。
// 外层决定当前选择有哪些片段，内层只组合这些目标能共同使用的字段。
// 视频、图片和音频共用同一组外观，不代表它们的效果处理流程已经共用。
// 正式页按构图能力清单提供回调，独立样板继续演示其他字段的草稿行为。
// 展示默认值时同时说明来源，避免用户把100%误读成已读到真实工程效果。
// 素材库高亮与这里的targets没有绑定，浏览素材不会抢走属性目标。
// 多选目标必须有各自身份，不能把相同文件名当成同一个片段去重。
// 内容滚动归propertyBody，标题、选中名称和来源说明保留在外侧。
// 空选择仍保留R04外壳，紧凑面板打开时不会因为没有字段而高度塌陷。
// 这里不查文件、不读取浏览器视频尺寸，也不推断当前画面有没有成功解码。
// 探测事实已经在asset里，效果默认值则由property-model根据项目决定。
// 这两个来源分开，可以在媒体坏掉时仍保留可理解的选择与项目参数。

// 兼容 asset/clipId 的旧调用处仍显式适配成目标，不再解析固定显示字符串。
// 新调用处传 targets，空数组明确表示无选择，不能回落到演示片段。
// 提交与重置都只通知意图，真实效果未接通时不传回调，字段自动禁用。
interface InspectorProps {
  asset?: EditorMediaAsset | null; clipId?: string; targets?: readonly InspectorTarget[];
  project?: EditorPreviewProject;
  editableKeys?: readonly PropertyKey[]; locked?: boolean; live?: boolean;
  onCommit?: (key: PropertyKey, value: number) => void;
  onReset?: (keys: PropertyKey[]) => void;
}

// targets显式传空数组时优先级高于兼容asset，不能用length判断后退回样例。
// 旧样板还用asset/clipId传单个目标，所以兼容入口在本文件统一适配。
// 正式宿主始终传targets与project，不依赖DEMO默认参数。
// onCommit只传字段键与有限数，不能接收任意数组来改时间线安排。
// onReset接一组当前可见字段，音频重置不会顺便重置画面位置。
// 调用者拥有目标集合，回调不再传文件名来要求它做模糊查找。
// 没有工程保存回调，也没有“应用成功”通知槽，避免表单样板冒充真实效果。
// 这里的可选回调表示明确能力，不应传空函数只为了把disabled去掉。
// 标签映射沿用功能域词条，X/Y明确写出项目像素方向，避免合成一个不可编辑字符串。
// 普通模块的 t 在渲染时调用，语言切换后不会保留模块加载时的旧文字。
const LABELS = { scale: "scale", x: "positionX", y: "positionY", rotation: "rotation", opacity: "opacity", speed: "speed", volume: "volume", fadeIn: "fadeIn", fadeOut: "fadeOut", duration: "duration" } as const;

// 标签表只做字段键到翻译键的映射，范围和精度不在这里重新定义。
// 这样切到英文仍提交同一个scale，而不是把“Scale”文字作为业务字段名。
// 标题和单位分别传给公共字段，数字草稿不需要解析带px的输入文本。
// positionX和positionY是两个独立字段，错误可以准确标到其中一个方向。
// 原来合并成“960,540”的字符串无法独立提交，也无法表达单方向混合值。
// 保留原功能域词条，语言集合继续由项目i18n决定，不新增编辑器专用Context。

// 同一个淡入淡出组同时服务视频与音频，回调绑定的是当前选中目标集合。
// key由选择ID和字段键构成，换对象不会保留前一片段的未提交草稿。
// 分组折叠仍交给 EditorGroup，A/B不共享展开值或字段错误。
// 重置按钮只在有真实样板回调时启用，不用空函数冒充正式效果重置。
function InspectorSection({ fields, targets, project, onCommit, onReset, editableKeys, locked }: { editableKeys?: readonly PropertyKey[]; locked?: boolean; fields: PropertyField[]; targets: readonly InspectorTarget[]; project: EditorPreviewProject; onCommit?: InspectorProps["onCommit"]; onReset?: InspectorProps["onReset"] }) {
  // 本分组只接非空fields，外层按有效字段的组名生成它，fields[0]因而有来源。
  // 单个分组共享一次重置意图，重置按钮与折叠按钮是兄弟，不嵌套button。
  // 字段key包含目标身份集合，换片段时销毁旧草稿，不把旧输入带到新对象。
  // 顺序也纳入key，因为代表值依赖首目标；改顺序时旧混合草稿不能继续代表原集合。
  // epoch只处理显式重置，不因每次render变化，普通打字不会反复卸载输入。
  // 如果确认值本来是默认值，外层回填相同数字并不足以清掉本地错误草稿。
  // 所以重置后让字段重新初始化，但不更换EditorGroup，展开状态仍保留。
  // 例如缩放确认100时输入abc，再点重置，必须回到100.00而不是继续保留abc。
  // 多选重置逐个目标使用默认值，字段再重新比较是否仍为混合。
  // 分组回调只收到本组字段，不能无意重置用户在另一个分组改好的样板值。
  // 正式页没有onReset，按钮原生禁用，epoch不可能被用户绕过业务边界更新。
  // reason和字段禁用说明来自同一词条，鼠标提示与读屏原因保持一致。
  // onCommit存在时逐字段注入目标明确的函数，公共输入无需认识片段列表。
  // propertyValue对每个字段独立计算mixed，不能因缩放不同让所有字段都显示横线。
  const group = propertyGroup(fields[0].key), reason = t(locked ? "toolBox.editorUi.trackLocked" : "toolBox.editorUi.effectUnavailable");
  const canEdit = (key: PropertyKey) => !locked && (!editableKeys || editableKeys.includes(key));
  const resetEnabled = !!onReset && fields.some(field => canEdit(field.key));
  // 重置既还原确认值，也丢弃本组未确认草稿；默认值没变时仍需一次新的输入生命周期。
  // 只更新字段的key，分组自身不卸载，用户的折叠选择不会因此复原。
  const [epoch, setEpoch] = useState(0);
  // 重置按钮被点击前，浏览器可能先触发字段blur；非法草稿仍会保留错误。
  // 随后reset意图重建字段，错误与草稿才一起被丢弃，不依赖blur校验成功。
  // 如果只setError(false)，非法文本还在，下一次失焦又会重复报错。
  // 如果把整个EditorGroup重新key掉，用户刚收起的组又会被强制打开。
  // 当前只重建组内字段，避免把数值恢复和面板展开混成一份状态。
  // epoch不进入values或项目文档，它是表单生命周期标记，不是媒体参数版本。
  // 目标集合的key与epoch组合，重置后再切对象也不会复用前一目标草稿。
  // 淡入和淡出在同一组，重置本组会同时恢复两者，其他组仍保留。
  // 多选类型交集变化由外层重组fields，不能对已消失字段继续调用重置回调。
  // 正式组还需通过能力和锁校验，不能只因onReset存在就显示可用重置。
  function reset() { onReset?.(fields.map(field => field.key)); setEpoch(value => value + 1); }
  return <EditorGroup title={t(`toolBox.editorUi.${group}`)} action={<EditorAction icon={RotateCcw} label={t("toolBox.editorUi.reset")} compact onClick={resetEnabled ? reset : undefined} disabledReason={!resetEnabled ? reason : undefined} />}>
    {fields.map(({ key, ...field }) => <EditorFloatField key={`${targets.map(target => target.id).join("|")}:${key}:${epoch}`} {...field} {...propertyValue(targets, project, key)} label={t(`toolBox.editorUi.${LABELS[key]}`)} disabledReason={reason} onCommit={onCommit && canEdit(key) ? value => onCommit(key, value) : undefined} />)}
  </EditorGroup>;
}

// 无选中展示项目事实，不能继续显示scene_02或上一个对象的默认效果参数。
// 分辨率/帧率来自项目，项目时长来自片段最晚结束点，不对素材库时长求和。
// 只读文字不是可编辑输入，避免给项目设置开一个尚未接通的提交入口。
function ProjectProperties({ project }: { project: EditorPreviewProject }) {
  // 项目事实是只读dl，不能将其包装成无回调但看似可调的数值字段。
  // 分辨率决定将来变换的坐标单位，不是当前节目画布的屏幕尺寸。
  // fps取工程时间模型，不因用户最后浏览了24fps素材而自动变成24。
  // 总时长从宿主project传入，删除末段后的缩短应随参数更新展示。
  // 空选择不意味着空工程，因此项目时长可能仍大于零。
  // “未选片段”的提示与“没有共同字段”分开，避免用户误以为工程丢了素材。
  // 数字格式仅影响读取，不提供保存、重新探测或项目设置修改能力。
  // 组件没有缓存上一个片段，因此空态不会残留scene_02的文件名。
  const { t } = useTranslation();
  return <><EditorPlaceholder state="empty" message={t("toolBox.editorUi.noClipSelected")} /><dl className={styles.projectFacts}><dt>{t("toolBox.editorUi.projectParameters")}</dt><dd>{project.width} × {project.height}</dd><dt>{t("toolBox.editorUi.frameRate")}</dt><dd>{project.fps}fps</dd><dt>{t("toolBox.editorUi.duration")}</dt><dd>{project.duration.toFixed(2)}s</dd></dl></>;
}

// 外壳保留 R04 与稳定片段标记，素材选择不能通过传入素材高亮改变属性目标。
// 文件名不承担身份，两个同源实例在目标数组里仍有不同的id。
// 多选只展示类型交集；没有共同字段就明确提示，不随机借用第一项全部属性。
// 正式片段没有覆盖值时提示默认来源，样板有values时说明其只是独立确认值。
// 头部不再依赖可能破损的封面，缺图不会把属性名挤到错误位置。
// editableKeys是已接通的效果清单，live只是说明文字，不能充当写入权限。
// 正式传入五个构图键，样板不传清单时保留原有演示编辑能力。
// 这使同一个FloatField仍能验证速度草稿，而正式速度字段保持只读。
// locked在组级别合并权限，不能仅让画布拒绝拖动而数字仍能修改。
// 组重置以该组至少一个有效可编辑字段为前提，不按onReset存在与否直接启用。
// 音频类型由inspectorFields排除构图组，不用CSS把视频字段藏起来。
// 分离音轨的源素材虽然仍是视频文件，宿主传入的类型已经适配为audio。
// 因此是否显示X/Y由安排通道决定，不由文件扩展名决定。
// 默认中心来自project，正式确认值来自target.values，两者不能互换。
// 多选的混合值继续由原propertyValue计算，不能拿首项确认值盖住混合状态。
// 输入控件持有字符串草稿，检查器只向外回报合法数值。
// Enter和失焦复用同一个字段提交机制，未输入完整的负号不会写工程。
// 字段错误在控件旁显示，不用全局通知打断连续调整。
// Escape恢复当前确认值；画布手势的Escape则由活跃捕获优先处理。
// 重置epoch仍只重建本组字段，另一组草稿不会因构图重置被清空。
// 切换目标集合改变字段key，上一片段未提交的文字不能带到下一片段。
// 主题切换不改变目标key，所以不会无故丢失正在编辑的草稿。
// 无目标时显示工程尺寸和时长，不把默认中心伪装成已选片段属性。
// 错误回调和保存能力没有加入这个展示组件，工程写入仍由宿主命令负责。
// 选择、字段草稿、展开状态分别拥有生命周期，共用外壳不等于共用状态。
export function ClipInspector({ asset = DEMO_ASSETS[1], clipId, targets, project = DEMO_PROJECT, onCommit, onReset, editableKeys, locked, live = false }: InspectorProps) {
  // 选择集合每次由参数构造，组件不维护第二份selectedId来和时间线竞争。
  // undefined表示旧调用接口，[]表示明确无选择，两者必须区别对待。
  // group集合来自交集结果，用Set去重保持首出现顺序，不按翻译标题排序。
  // 共有变换仍是一组，视频与图片不各生成一份重复的X/Y字段。
  // 单选标题显示原文件名，多选显示数量，不伪装成第一项就是全部目标。
  // 长名称通过title保留全名，视觉省略不会更改对象身份。
  // data-editor-inspector-clip保留首项标记供现有回归观察，数量另有count表达。
  // 这份标记不是写入接口，自动化仍须通过公开操作检查实际显示结果。
  // 有目标但交集为空时，仍显示选择数量与说明，让用户理解为什么没有输入框。
  // 没目标时直接显示项目事实，不先生成默认视频字段再靠CSS隐藏。
  // 正式来源说明区分构图已接通与速度等未接通；样板说明指出数值只属于演示。
  // 不通过按钮颜色判断是否为样板，能力来自是否注入回调。
  // 所有组共享同一字段实现，输入精度和错误规则修改后会同时作用于淡入与变换。
  // 组与字段状态却各归自己的React实例，A的折叠和错误不能传播到B。
  // 主动重置或切对象才更新字段身份，主题切换不会清掉当前草稿。
  // 正式构图由宿主传已确认值和字段能力，速度与淡入淡出不因有回调就自动开放。
  // 检查器只提交数值意图；画布变换在媒体适配层，保存和导出依旧独立。
  const { t } = useTranslation();
  const selected = targets ?? (asset ? [{ id: clipId ?? DEMO_CLIPS[1].id, asset, duration: asset.duration ?? 0 }] : []);
  const fields = inspectorFields(selected), groups = [...new Set(fields.map(field => propertyGroup(field.key)))];
  const name = selected.length > 1 ? t("toolBox.editorUi.selectedCount", { count: selected.length }) : selected[0]?.asset.name;
  return <aside data-editor-region="R04" data-editor-inspector-clip={selected[0]?.id} data-editor-inspector-count={selected.length} className={styles.inspector} aria-label={t("toolBox.editorUi.inspector")}><h2 className={styles.panelTitle}>{t("toolBox.editorUi.inspector")}</h2>
    {selected.length ? <><div className={styles.selectedClip}><strong title={name}>{name}</strong></div><p className={styles.propertyNotice}>{t(live ? "toolBox.editorUi.transformLive" : onCommit ? "toolBox.editorUi.propertySampleOnly" : "toolBox.editorUi.propertyDefaults")}</p><div className={styles.propertyBody}>
      {groups.map(group => <InspectorSection key={group} fields={fields.filter(field => propertyGroup(field.key) === group)} targets={selected} project={project} onCommit={onCommit} onReset={onReset} editableKeys={editableKeys} locked={locked} />)}
      {!fields.length && <EditorPlaceholder state="empty" message={t("toolBox.editorUi.noCommonProperties")} />}
    </div></> : <div className={styles.propertyBody}><ProjectProperties project={project} /></div>}
  </aside>;
}

"use client";

// 素材面板的独立状态样板，不参与默认演示工程或真实文件管理。
// 同时挂载两个实例，检验共享组件是否错误共用搜索或选中状态。
// 复用 UI-02 的行、按钮和占位；本文件只提供数据与场景开关。
// 所有资源来自随包图片，不读取用户路径，也不请求媒体探测服务。
// 样板控制是显式切换固定夹具，不是模拟异步导入成功。
// 场景离开后局部状态销毁，不写入工程或用户设置。
import { useState } from "react";
import { useTranslation } from "@/i18n";
import { EditorAction } from "./editor-controls";
import { DEMO_ASSETS } from "./editor-demo";
import { MediaPanel, type EditorMediaAsset } from "./editor-panels";
import styles from "./editor.module.css";

// 同一个长列表包含三种媒体，搜索和分类必须取交集。
// 第一个视频只在副本中改名，默认工程仍显示 scene_01.mp4。
// 超长名称保留完整 title，不能让文字撑宽缩略图槽或整个面板。
// loading 行固定等待，不会在几秒后假装探测成功。
// error 行固定不可用，即使列表存在也不能选择该行。
// 图片没有封面与整个文件不可用不同，缺封面仍允许选择。
// 音频没有封面属于正常展示，应继续使用同一个静态波形。
// 重复音频具有独立稳定 ID，选择其中一行不能高亮所有副本。
// 重复项用于让列表实际超出滚动槽，不增加默认工程素材数量。
// 这些条目不对应新磁盘文件，不应出现在真实最近导入记录。
// 数组中的旧对象只读复用，替换名称时用新对象，不修改共享常量。
// 编号只作为样例文件名的一部分，不被解释为帧号或时间线坐标。
// 数据定义在组件外避免输入每个字符时重新构造长列表。
// 不在这里缓存选中 ID，内容共享与交互状态共享是两回事。
// duration 为零或 null 的含义由行组件保留，不为样板另做格式化。
// 长列表末尾同样走 MediaItem 回调，滚动不会产生另一套选择实现。
// 显式类型保留可选 state，普通素材没有该字段时仍默认可用。
// 本数据不含绝对路径，因此不会把本机隐私文件名写入运行截图。
const EDGE_ASSETS: readonly EditorMediaAsset[] = [
  ...DEMO_ASSETS.map(asset => asset.id === "scene-01" ? { ...asset, name: "scene_01_long_filename_1920x1080_spring_landscape_final_revision_with_extended_location_camera_take_color_grade_version_and_original_source_reference_for_overflow_validation.mp4" } : asset),
  { ...DEMO_ASSETS[0], id: "probing", name: "probing.mp4", state: "loading" },
  { ...DEMO_ASSETS[0], id: "unavailable", name: "unavailable.mp4", state: "error" },
  { ...DEMO_ASSETS[2], id: "no-cover", name: "no_cover.png", cover: null },
  ...Array.from({ length: 12 }, (_, index) => ({ ...DEMO_ASSETS[3], id: `voice-${index}`, name: `voice_${index + 2}.wav` })),
];

// 固定场景用现有状态词条，不引入与真实媒体后端同名的命令。
// ready 恢复原五项，edge 专门展示异常行与滚动边界。
// empty 是真正传入空数组，与筛选后零结果分别验收。
// loading/error 属于整库状态，不能只改变一个素材缩略图。
// 每次场景切换都明确重新挂载本实例的面板，搜索回到确定起点。
// 这种重置只用于样板场景，默认面板筛选不会重新挂载或丢选择。
// 场景列表同时驱动按钮标签和 pressed，避免文案与实际样例不一致。
// 不用 setTimeout 把 loading 推进成 ready，避免伪造业务完成。
// 没有“重试成功”按钮，来源错误只作为可检查的静态状态。
// 场景 ID 是封闭联合，不接收 URL 或用户输入来读取任意文件。
const SCENARIOS = ["ready", "loading", "empty", "error", "edge"] as const;
const SCENARIO_LABELS = { ready: "mediaReady", loading: "loading", empty: "empty", error: "error", edge: "mediaEdge" } as const;

// A/B 各自保存场景，切换 A 不重置 B 的条件或选择。
// 面板内部保存查询与素材选择，样板只管理外部固定数据状态。
// 这像两个独立书架共用同款书签夹，每个夹子仍记自己的页码。
// 对应机制是分别挂载 MediaPanel，而不是在父组件共享 selected。
// 空库保留搜索工具外壳，真实导入按钮仍原生禁用。
// 整库等待/错误保留导入原因，不让场景切换启用真实业务。
// 场景按钮使用公共 EditorAction，焦点与主题外观同步主工作区。
// 素材区域高度由局部样板规则固定，只有结果槽滚动。
// 两实例使用可读 id 标记，测试无需依赖翻译或 CSS 哈希定位。
// key 只包含本实例场景，不因另一实例切换而改变。
// 选素材没有片段回调参数，不可能从样板误创建正式时间线片段。
// 这里不复用旧视频工具的真实导入状态，因为它有不同的副作用边界。
// 无封面素材仍传 onSelect 由面板处理，能验证异常与可用性的区别。
// 长列表只为 UI 验证，不声称覆盖大库分页、探测吞吐或媒体解码性能。
// JSX 装配沿用 sampleInstance 的公共边框，不创建无意义的卡片包装器。
// 组件卸载没有需要取消的请求、计时器或媒体播放资源。
function MediaPanelSample({ id }: { id: string }) {
  // 这里的场景值只决定传给面板的数据，不会改变面板的筛选算法。
  // ready 与 edge 的行集合不同，但两者都验证相同的 MediaItem 外壳。
  // loading/error 是整库状态，单行 state 则保留在 EDGE_ASSETS 中。
  // 选中状态由 MediaPanel 自己管理，父样板不读取或重写 selected ID。
  // key 让场景切换回到明确的演示起点，正式面板不会这样重置。
  // 场景按钮按下态来自这个局部状态，两个实例不会共享按下按钮。
  // 传空数组是空库的真实输入，不能用 CSS 隐藏五项来模拟空态。
  // 传入只读数组后，面板过滤不会修改 EDGE_ASSETS 的顺序或对象。
  // 每个场景都保留导入按钮，才能证明错误/空库没有误启用真实导入。
  // 面板高度由样式固定，结果槽滚动而不是让页面重复出现横向滚动条。
  // 这里不传 onSelect，素材选择仍在面板内部完成，不向工程广播。
  // 这说明展示组件可以在无业务接收方时独立呈现纯 UI 交互。
  // 场景标题和按钮使用翻译键，切换语言不会改变状态 ID。
  // 本函数没有异步副作用，卸载时不需要取消探测或播放任务。
  // 真实业务接入时可从外部传 assets 和回调，不应复制这套演示分支。
  const { t } = useTranslation();
  const [scenario, setScenario] = useState<typeof SCENARIOS[number]>("ready");
  return <section className={`${styles.sampleInstance} ${styles.mediaSample}`} data-editor-media-sample={id}>
    <h2>{t("toolBox.editorUi.media")} · {id}</h2>
    <div className={styles.sampleActions}>{SCENARIOS.map(value => <EditorAction key={value} label={t(`toolBox.editorUi.${SCENARIO_LABELS[value]}`)} pressed={scenario === value} onClick={() => setScenario(value)} />)}</div>
    <MediaPanel key={scenario} assets={scenario === "empty" ? [] : scenario === "edge" ? EDGE_ASSETS : DEMO_ASSETS} state={scenario === "loading" || scenario === "error" ? scenario : "ready"} />
  </section>;
}

// 此入口位于现有样板页，默认工作区不增加调试按钮或额外素材。
// 两实例渲染完全相同的组件，仅 id 和局部状态不同。
// 主题改变继续使用同一 DOM，不能靠两套深浅页面掩盖共享样式问题。
// 窄窗口由已有 sampleGrid 换成一列，不复制移动版素材面板。
// 每个实例内保留独立滚动槽，页面负责两个实例之间的纵向滚动。
// 顶部说明沿用样板页已有的业务边界声明，避免每行重复提醒。
// 标题使用双语词条，与 UI-02 的控件样板明确区分。
// 新样板放在原 A/B 之后，既有控件回归的定位与场景顺序不变。
// 返回默认编辑器仍使用页面原有入口，不额外创建另一套导航。
// 后续 UI-04 的节目状态不能因为这些素材样例通过就标为已完成。
export function EditorMediaSamples() {
  const { t } = useTranslation();
  return <section><h2>{t("toolBox.editorUi.mediaSamples")}</h2><div className={styles.sampleGrid}><MediaPanelSample id="A" /><MediaPanelSample id="B" /></div></section>;
}

"use client";

// R02–R04 只负责上区的独立展示，不导入 useClipEditor 或 FFmpeg 服务。
// 旧 PreviewStage 绑定真实源视频事件和 trim，本轮不改它与 GIF 共用的契约。
// 样板仍映射静态封面；正式单源时钟和解码通过插槽注入，节目合成未接入。
// 素材列表和属性面板各自滚动，节目预览保留固定的标题与走带控制条。
// 静态图片与真实视频共用ClipCanvas的项目几何，媒体解码各由原适配负责。
// ProgramPreview仍负责frame尺寸，不让源宽高把整个预览容器撑变形。
// 图片节点保留原来的缺图与onError处理，构图不能把坏图改报成成功。
// 源查看分支继续返回原始图片节点，避免把片段的X/Y带回素材库。
// 节目图片分支才包裹构图层，调用者可以只读显示已确认变换。
// 没有编辑回调时不创建操作按钮，样板查看不冒充正式工程编辑。
// 传给真实媒体的surface槽仍优先，不在公共容器额外挂一个封面播放器。
// 这保证视频首帧成功后画面来自video，静态封面不覆盖真实帧。
// 基础图片尺寸优先真实元数据，其次构建期静态资源尺寸。
// 封面只是URL字符串时不能从文件名推测源分辨率。
// picture几何采用项目比例，不继承素材卡片的裁切样式。
// 单源透明度让黑色项目底透出，这只是当前片段效果，不是多个视频相互混合。
// 选框不放在NextImage内部，图片加载和交互焦点不互相控制。
// 缺素材引用仍走现有missing状态，不默认使用DEMO第一张图片补位。
// 同一ProgramPreview继续服务正式视频、独立图片样板和素材查看。
// 因此公共标题和控制条的改动无需三个调用场景分别维护。
// 真实图片导入尚未接通，当前图片能力是模型和共享渲染支持。
// 自动图片样例只验证构图几何，不声称已经完成用户磁盘图片导入。
// 图片没有音轨或播放进度，构图层也不能替它生成假时间事件。
// 真实视频的播放时钟仍由LiveSourcePreview拥有，不移到图片展示组件。
import { ClipCanvas, type CanvasEdit } from "./clip-canvas";
import type { ClipTransform } from "./clip-transform-model";
import Image, { type StaticImageData } from "next/image";
import { useState, type ReactNode, type DragEvent } from "react";
import type { VideoProbeResult } from "@/types/electron-api";
import { EditorPlaceholder } from "./editor-controls";
// 图标包含音视频类型与实际动作，音频不借用“可见”图标表达静音。
// 所有未接通动作复用 EditorAction，不额外创建可点击的伪菜单。
// 装饰图标用 aria-hidden，让文件名和文本标签承担可访问含义。
import { AudioLines, Camera, ChevronDown, ImageIcon, Play, Search, SkipBack, SkipForward, Upload, Video } from "lucide-react";
import { useTranslation } from "@/i18n";
// 默认资源来自演示模块，正式调用方显式注入真实数组和项目参数。
// 素材行用联合类型约束媒体种类，静态封面可以为空但名称始终存在。
// 行只接收静态图片或已生成的小封面，不直接读取用户视频路径。
import { DEMO_ASSETS, DEMO_PROJECT } from "./editor-demo";
import { EditorAction } from "./editor-chrome";
import styles from "./editor.module.css";
import { formatEditorTimecode } from "./editor-timecode";

// 音频行、时间轴音频片段共用同一个占位图形，减少两套伪波形样式。
// 这里绘制的对称竖线只是视觉占位，不从任何音频读取采样值。
// aria-hidden 防止读屏把装饰线当作需要逐项阅读的音频采样数据。
// 规律长度用于稳定截图，不使用 Math.random 导致服务端与客户端不一致。
// 图形继承 currentColor，主题切换只改变容器颜色而不染节目画面。
// width/height 交给容器，素材行与片段可以用同一 DOM 适配不同宽度。
// wave 的坐标固定，不参与工程秒数到时间轴宽度的换算。
// 后续真实波形接入时替换此内容组件，不改素材或片段的外壳几何。
export function DemoWaveform() {
  // viewBox 中点为 16，每根竖线围绕中点摆放，不对应实际声道数。
  // preserveAspectRatio=none 只伸展装饰波形，不作用于节目图片。
  // SVG 不生成 base64 图片副本，两个音频素材和两个轨道可以共享同一内容模板。
  // strokeLinecap 的圆头使小尺寸音频封面仍可辨认，深色不需换另一张贴图。
  return <svg viewBox="0 0 120 32" preserveAspectRatio="none" className={styles.waveform} aria-hidden="true"><path d="M3 14v4m5-9v14m5-11v8m5-15v22m5-17v12m5-19v26m5-17v8m5-11v14m5-20v26m5-22v18m5-12v6m5-14v22m5-25v28m5-19v10m5-14v18m5-22v26m5-18v10m5-14v18m5-12v6m5-17v28m5-20v12m5-9v6m5-12v18m5-15v12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg>;
}

// 同一个素材行同时呈现视频、图片、配音与音乐，尺寸与截断规则只维护一份。
// 这里只改变素材选择，点击不会暗中修改片段属性或节目画面。
// duration=null 的图片不显示秒数，避免误把时间轴实例长度当成源时长。
// Next Image 复用项目已有图片组件链路，静态导出不引入图片处理服务。
// 每张封面占用相同槽位，无封面的音频用明确波形图形而非破损图片。
// 名称拥有 title，长文件名只在视觉上省略，完整名称仍可查看。
// 选中态同时显示细边框和浅色表面，aria-current 跟随调用方状态。
// 素材行不是时间轴按钮，未来 onSelect 只通知素材区，不自动控制播放头。
// 未接通原因沿用共享词条，不输出测试脚本或内部技术信息。
// 原生按钮支持键盘选择；加载或错误行禁用，不产生假文件导入。
// id 用作 React key，列表排序变化后不会复用另一素材的 DOM 身份。
// 字段参数只传当前素材，不把整个全局 store 注入行组件。
// 素材描述只承载行需要的信息，不包含时间轴位置或片段属性。
// 同一个源素材可以被多个片段引用，不能把片段 ID 填进这里的 id。
// name 是显示与搜索的原始文件名，搜索时不修改这个值。
// kind 来自已知演示数据，不通过后缀猜测媒体是否可播放。
// duration 为 null 表示没有源时长，图片不会因此多出一个虚构秒数。
// cover 同时支持打包静态图片与导入适配器生成的小封面，不读取整个视频。
// state 可随素材内容注入，让正式面板和样板复用同一行。
// 缺封面仍可选择，探测中和不可用行则保持禁用。
// 行状态不自动推进，也不代表已经执行了真实媒体探测。
// 这份接口不带删除、导入或播放方法，避免展示组件获得业务副作用。
// readonly 数组可由外部传入，面板不会改写调用方的素材对象。
// 新增状态字段是可选的，UI-02 的已有调用仍默认 ready。
// 独立 state 参数保留兼容性，显式传入时覆盖素材自带状态。
// 这样异常夹具无需复制一份带特殊样式的素材行。
export interface EditorMediaAsset {
  id: string;
  name: string;
  kind: "video" | "image" | "audio";
  duration: number | null;
  cover: StaticImageData | string | null;
  state?: "ready" | "loading" | "missing" | "error" | "cancelled";
  sourcePath?: string;
  sourceUrl?: string;
  metadata?: VideoProbeResult;
  notice?: string;
}
export function MediaItem({ asset, selected = false, onSelect, state = asset.state ?? "ready", onDragStart, onDragEnd }: { asset: EditorMediaAsset; selected?: boolean; onSelect?: () => void; state?: EditorMediaAsset["state"]; onDragStart?: (event: DragEvent<HTMLButtonElement>) => void; onDragEnd?: () => void }) {
  // 视频的小摄像图标与图片山景图标来自明确 kind，防止把 png 当成有时长视频。
  // 音频同用 AudioLines，不根据 voice/music 名称猜测是否内嵌视频。
  // alt 为空是因为相邻文件名已标识素材，避免一行被读屏重复念两遍。
  // fill 的父容器有已知比例和 position:relative，不会先塌陷再加载跳动。
  // 每个媒体只创建一个封面槽，缺封面不会再留一个空图片重叠加载。
  // duration 使用显式 null 判断，合法的零秒探测结果未来也不会被误当成图片。
  // `s` 为数值单位符号，媒体类型文字本身由 i18n 负责。
  // asset.id 不拼进文件路径，不存在把用户输入转成任意磁盘读取的路径。
  const { t } = useTranslation();
  const [failedCover, setFailedCover] = useState("");
  // 波形只属于音频，图片或视频没有封面时不能用波形冒充预览。
  // 缺图仍可选择；读取中和不可用素材才由下方按钮规则禁用。
  // 失败按 URL 记忆，后续同一行换封面后可以加载新图。
  // 显式 loading/error 优先于封面判断，错误素材不能被降级为普通缺图。
  // 音频的 null 封面是正常数据，并不表示音频缺失或加载失败。
  // displayState 只是视图结果，不写回 asset，其他实例仍读自己的封面状态。
  // 占位替换只发生在固定缩略图槽，名称、时长与素材 ID 不会跟着换掉。
  // 因此加载失败不需要重新生成列表 key，也不清空外层已选素材。
  // 不在这里尝试探测媒体或补做解码，缺封面的真实恢复留给后续素材业务。
  const missingCover = asset.kind !== "audio" && (!asset.cover || (typeof asset.cover === "string" ? asset.cover === failedCover : asset.cover.src === failedCover));
  const displayState = state === "ready" && missingCover ? "missing" : state === "cancelled" ? "missing" : state;
  const metadata = asset.metadata;
  const Icon = asset.kind === "audio" ? AudioLines : asset.kind === "image" ? ImageIcon : Video;
  return <li><button type="button" disabled={!onSelect || state === "loading" || state === "error" || state === "cancelled"} onClick={onSelect} draggable={state === "ready" && !!onDragStart} onDragStart={onDragStart} onDragEnd={onDragEnd} data-editor-asset={asset.id} aria-current={selected ? "true" : undefined} aria-busy={state === "loading" || undefined} title={asset.name} className={styles.mediaItem}>
    <span className={styles.mediaCover}>{displayState && displayState !== "ready" ? <EditorPlaceholder state={displayState} message={asset.notice || t(`toolBox.editorUi.${displayState}`)} compact /> : asset.cover ? <Image src={asset.cover} onError={() => setFailedCover(typeof asset.cover === "string" ? asset.cover : asset.cover?.src || "")} alt="" fill sizes="100px" unoptimized={typeof asset.cover === "string"} className="object-cover" /> : <DemoWaveform />}</span>
    <span className={styles.mediaDescription}><strong>{asset.name}</strong><small><Icon size={14} />{t(`toolBox.editorUi.${asset.kind}`)}{asset.duration !== null && ` · ${metadata ? asset.duration.toFixed(2) : asset.duration}s`}</small>{metadata && <small className={styles.mediaMetadata}>{metadata.width}×{metadata.height} · {metadata.fps}fps · {metadata.hasAudio ? t("toolBox.editorUi.audioTrack") : t("toolBox.editorUi.noAudioTrack")}</small>}{asset.notice && <small className={styles.mediaNotice}>{asset.notice}</small>}</span>
  </button></li>;
}
// 封面失败按 src 记录，调用方换成另一张图片时不会继承上一张的缺图状态。
// 失败只改变当前素材行，不能使另外四份资源一起显示不可用。
// 显式 state 的优先级高于图片事件，loading 不会因旧图已经解码就变 ready。
// 组件不在失败后无限请求同一个 URL，用户不会被无意义重试占用资源。
// 没有封面的音频默认显示波形占位，不把正常音频归为 missing。
// 缺图只说明封面问题，未来业务是否允许选中由 onSelect 明确决定。
// state 为 error/loading 时即使传入回调也禁用，避免无效素材触发后续动作。
// aria-current 只跟随外部选择，公共行不决定哪份素材属于当前节目。
// 选择素材和选择片段的身份分开，一份素材可以对应时间轴多个实例。
// data-editor-asset 记录素材稳定 ID，文件名重命名不会改变测试定位身份。
// 文件名作为可见主要文本，title 提供被省略部分，不再额外弹出自制提示框。
// 封面 alt 为空因为文字已描述同一资源，减少辅助阅读重复信息。
// loading 的 aria-busy 位于行按钮，局部等待不会误标整个编辑器正在处理。
// 错误占位使用 alert，而缺图使用 status，让状态变化语义不同。
// 无回调的状态样例仍保留完整名称和媒体类型，不出现无法解释的空灰行。
// kind 的联合限制为三种媒体，不根据 name 后缀猜测用户改名文件的类型。
// 样例用静态图片；真实封面在导入边界生成，行无需另建媒体加载流程。
// 不为这个控件直接调用 readFile 或上传缩略图，保持渲染层隔离。
// 浮点字段复用只改变输入外壳，原复合“位置”展示仍不伪装成可编辑数值。
// 属性行解析失败时保留原显示路径，不能把复合值错误转成 NaN。
// 正式属性没有 onCommit，说明当前只是样例参数，不向工程状态写入。
// 属性折叠归每个 EditorGroup，两个分组不因同名而共用 open。
// 重置动作仍是禁用 EditorAction，不能清空数值制造已经接通的错觉。
// 预览与素材选择继续独立，UI-02 不负责切换静态节目图或时钟。

// R02 顶部导入、搜索和分类固定，只有列表占据剩余高度并独立滚动。
// 搜索与筛选只处理调用方传入的数组，面板自身不启动文件探测。
// 同一面板用于默认五项素材和独立状态样板，不复制列表 JSX。
// 有导入回调才启用系统入口，演示工程不传回调，避免读入用户文件。
// 搜索框有独立名称，placeholder 不是唯一的可访问提示。
// 类别文案来自双语词条，不按当前语言手拼视频类型。
// 类型按钮的 pressed 反映实际筛选条件，不再固定高亮“全部”。
// 素材面板的区域名称与 R02 对应，测试可核对区域而不用依赖中文选择器。
// 该区不添加第二个关闭窗口按钮，侧栏展开收起由后续布局任务明确。
// min-height 由工作区统一定义，长列表不能把节目预览推到页面外。
// assets、整库状态和选择回调是面板的最小注入边界。
// 不接收片段列表，因此选素材没有通路修改时间轴或属性面板。
// 搜索与类型取交集，先选音频再搜 voice 只会留下匹配音频。
// 搜索两端空格与英文大小写不影响匹配，原文件名用于显示和 title。
// 选中 ID 像图书馆的书签，筛选只遮住书架，不把书签移到第一本可见书。
// 对应机制是独立保存 selected，不在筛选结果变化时重设选择。
// 取消条件后原选中行重新出现，不自动选中结果首项。
// 两个面板分别执行 hooks，不使用模块级变量或共享工程 store。
// 初始 scene-02 仅当输入中存在同 ID 时才显示高亮。
// onSelect 是素材意图通知，调用者不能从这里误收到片段位置。
// 状态变为 loading/error 时旧数组也不渲染，避免继续操作过期素材。
// 输入和分类在整库不可用期间禁用，不把错误误报成“搜索无结果”。
// 空库表示输入原本无素材，无结果表示有素材但不符合当前条件。
// 两者分别使用不同文字，只有后者提供清除条件的纯 UI 操作。
// 清除条件不会清除选中 ID，也不会制造新的素材或片段。
// 状态播报位于列表之外，结果从一项变成零项时仍可读到数量。
// 所有提示复用 EditorPlaceholder，不另画四套空态外壳。
// 加载是调用方传入的固定状态，不启动定时器假装探测完成。
// 错误说明指向素材来源不可用，本轮没有空函数重试按钮。
// 默认素材仍保持原图的顺序和五个名称，筛选不做隐式排序。
// 只有滚动列表占据剩余高度，控件不会被长列表带走。
// 键盘沿用搜索输入和原生按钮行为，Enter/Space 可选素材。
// Escape 只清当前搜索词，不改变分类或触发播放器快捷键。
// 没有注册 document 快捷键，离开页面无需额外清理监听器。
// 演示实例不提供导入回调；正式实例的回调由自己的会话管理。
// 提供选择回调不会意外启用导入、播放或媒体探测。
// 空库时仍能编辑搜索条件，恢复素材数据后会应用用户保留的条件。
// 样板切换数据时使用新的实例 key，让每个显式场景有确定起点。
interface MediaPanelProps {
  assets?: readonly EditorMediaAsset[];
  state?: "ready" | "loading" | "error";
  selectedId?: string | null;
  onSelect?: (id: string) => void;
  onImport?: () => void;
  onCancelImport?: () => void;
  importBusy?: boolean;
  importNotice?: string;
  // LIVE-02只给真实ready视频注入拖动；样板不会自动获得文件或工程能力。
  // 添加末尾是拖入的键盘替代，业务回调在外部共享碰撞校验。
  // selectedId仍属于素材，添加片段不能反向替换本行高亮。
  onAssetDragStart?: (event: DragEvent<HTMLButtonElement>, id: string) => void;
  onAssetDragEnd?: () => void;
  onAddToTimeline?: (id: string) => void;
}

// LIVE-02沿用这份素材行，不为入轨拖动复制搜索、筛选和封面布局。
// onAssetDragStart只在ready素材上注入，失败行仍保持禁用原因。
// 外部文件导入归onImport，内部入轨归onAssetDragStart，不能混用回调。
// 素材选中归selectedId，拖动成功不会通过onSelect把它改成另一行。
// “添加到V1末尾”读取当前可用视频选择，没有选择时说明为何不可执行。
// 此按钮传assetId给工程拥有者，不在面板内推算工程末尾秒数。
// 因此鼠标落点创建与末尾添加使用同一个命令校验和UUID规则。
// 素材duration仍是ffprobe事实，面板不显示片段取整后的工程占位长度。
// 筛选只影响可见行，不删除已在时间线中引用的素材。
// 样板不传入轨回调，仍只演示纯UI，不会生成真实工程安排。
// 导入busy与片段拖动分别显示，不把“正在探测”当成“正在移动”。
// 列表的滚动区继续只包结果，新增按钮不会跟随素材一起滚走。
export function MediaPanel({ assets = DEMO_ASSETS, state = "ready", selectedId, onSelect, onImport, onCancelImport, importBusy = false, importNotice = "", onAssetDragStart, onAssetDragEnd, onAddToTimeline }: MediaPanelProps) {
  // 分类条件不是排序规则，输入相同就保留调用方提供的行顺序。
  // 名字匹配包含扩展名，用户可以用 wav 查音频，也可以单独用类型按钮。
  // 空白查询相当于未搜索，不能因为误输入空格把整库藏起来。
  // 清除条件恢复 all，而 Escape 保留当前类型，两种操作有意不同。
  // 后者方便只改查询词继续查同类素材，不需要重新点分类。
  // 面板 ready 不表示每一行 ready；个别探测/失败由行自己的 state 表达。
  // 因而一个损坏素材不会禁用同库的其他可用项。
  // 整库失败时不读结果行的可用性，必须先恢复来源再允许操作旧内容。
  // 结果数量只统计匹配行，包括能看见但不能选的异常项。
  // 不把数量播报写成“可播放数量”，避免把 UI 匹配误称为解码验证。
  // 选择回调在明确点击后触发，不在首帧或输入每个搜索字符时触发。
  // 这使未来调用方可监听素材意图，而不误收筛选引起的工程编辑事件。
  const { t } = useTranslation();
  const [localSelected, setLocalSelected] = useState("scene-02");
  const [query, setQuery] = useState(""), [kind, setKind] = useState<"all" | EditorMediaAsset["kind"]>("all");
  const selected = selectedId === undefined ? localSelected : selectedId;
  const results = assets.filter(asset => (kind === "all" || asset.kind === kind) && asset.name.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  const placeholder = state !== "ready" ? state : "empty";
  const message = state === "loading" ? t("toolBox.editorUi.mediaLoading") : state === "error" ? t("toolBox.editorUi.mediaError") : assets.length === 0 ? t("toolBox.editorUi.empty") : t("toolBox.editorUi.noMediaResults");
  return <section data-editor-region="R02" className={styles.mediaPanel} aria-label={t("toolBox.editorUi.media")} aria-busy={state === "loading" || importBusy || undefined}>
    <h2 className={styles.panelTitle}>{t("toolBox.editorUi.media")}</h2>
    {/* R02：按钮和文件拖入只注入不同入口，最后都走调用方的同一个批次导入方法。 */}
    <div className={styles.mediaTools}><EditorAction icon={Upload} label={t("toolBox.editorUi.import")} onClick={onImport} busy={importBusy} disabledReason={!onImport && !importBusy ? t("toolBox.editorUi.mediaImportUnavailable") : undefined} accent /><label className={styles.search}><Search size={15} aria-hidden="true" /><input type="search" disabled={state !== "ready" || importBusy} value={query} onChange={event => setQuery(event.target.value)} onKeyDown={event => { if (event.key === "Escape") { event.stopPropagation(); setQuery(""); } }} aria-label={t("toolBox.editorUi.search")} placeholder={t("toolBox.editorUi.search")} /></label></div>
    {/* R02：末尾添加不打开文件选择器，禁用时明确要求先选择就绪视频。 */}
    {/* 和鼠标拖动共用同一个创建方法，素材列表选中不等于已创建片段。 */}
    {onAddToTimeline && <EditorAction label={t("toolBox.editorUi.addToV1")} onClick={() => { if (selected) onAddToTimeline(selected); }} disabledReason={!assets.some(asset => asset.id === selected && asset.kind === "video" && asset.state === "ready") ? t("toolBox.editorUi.selectReadyVideo") : undefined} />}
    {importBusy && <EditorAction label={t("toolBox.editorUi.cancelImport")} onClick={onCancelImport} />}
    {importNotice && <p className={styles.mediaNoticeBar} role="status">{importNotice}</p>}
    {/* 筛选像遮住货架的帘子，导入不会替用户改条件；隐藏项提供明确恢复入口。 */}
    {onImport && assets.length > results.length && <p className={styles.mediaNoticeBar} role="status">{t("toolBox.editorUi.hiddenMedia", { count: assets.length - results.length })}<EditorAction label={t("toolBox.editorUi.clearMediaFilters")} onClick={() => { setQuery(""); setKind("all"); }} /></p>}
    {onImport && <p className={styles.dropHint}>{t("toolBox.editorUi.dropHint")}</p>}
    {/* 分类与搜索共同生效，pressed 只由本实例 kind 决定。 */}
    <div className={styles.filters} role="group" aria-label={t("toolBox.editorUi.mediaTypes")}>{(["all", "video", "audio", "image"] as const).map(type => <EditorAction key={type} label={t(`toolBox.editorUi.${type}`)} pressed={kind === type} disabledReason={state !== "ready" ? message : undefined} onClick={() => setKind(type)} />)}</div>
    <span className="sr-only" role="status">{state === "ready" ? t("toolBox.editorUi.mediaResultCount", { count: results.length }) : message}</span>
    {/* 素材区滚动体：行选择不写片段属性，不向时间轴添加实例。 */}
    <div className={styles.mediaList} data-editor-media-results>
      {state === "ready" && results.length > 0 ? <ul className={styles.mediaRows}>{results.map(asset => <MediaItem key={asset.id} asset={asset} selected={asset.id === selected} onDragStart={onAssetDragStart && asset.kind === "video" && asset.state === "ready" ? event => onAssetDragStart(event, asset.id) : undefined} onDragEnd={onAssetDragEnd} onSelect={() => { setLocalSelected(asset.id); onSelect?.(asset.id); }} />)}</ul> : <EditorPlaceholder state={placeholder} message={message} />}
      {state === "ready" && assets.length > 0 && results.length === 0 && <EditorAction label={t("toolBox.editorUi.clearMediaFilters")} onClick={() => { setQuery(""); setKind("all"); }} />}
    </div>
  </section>;
}

// R03 沿用原预览容器，参数只描述选中片段和静态展示，不持有播放资源。
// 片段像节目单上的一条记录，assetId 是回到素材货架查原件的号码。
// 此处根据号码读取封面，而不是拿素材区当前高亮项冒充节目选中片段。
// 同一素材可被多个片段引用，预览仍保留片段自身的 id 和工程起止时间。
// 默认工作区与独立样板共享这个映射，不能各写一套封面查找逻辑。
// 主时间轴的交互选择属于 UI-06，本轮默认传入确定的 clip-02。
// 样板用已有片段壳切换参数，验证映射，不开启真实播放或时间线剪辑。
export interface EditorPreviewClip {
  transform?: ClipTransform;
  id: string;
  assetId: string;
  start: number;
  end: number;
  // 通道标记属于片段，不改源素材类型；省略时保留原静态与视频预览。
  // 分离视频静音，音频实例单独试听，两者不会偷偷开始多轨合成播放。
  // 这两项不是源文件元数据，也不通过IPC写回磁盘。
  audioOnly?: boolean;
  audioDetached?: boolean;
}
// 画布与时间码使用项目参数，不从缩略图的像素尺寸猜测输出分辨率。
// 宽高只决定节目画布比例，不把源封面拉伸到任意容器比例。
// 帧率必须是正整数；格式化函数对非法演示输入仍有明确回落。
// duration 是整个工程的长度，不等于一段素材的原始时长。
// 这些参数没有输出路径或解码句柄，不开放真实媒体处理能力。
// 对象按最小展示需要定义，不把整份工程 store 注入公共预览。
export interface EditorPreviewProject {
  width: number;
  height: number;
  fps: number;
  duration: number;
}
// 预览状态与媒体类型分开，音频没有图片不是“封面加载失败”。
// black 用于明确黑场样例，不伪造一张黑色图片当作已解码视频帧。
// empty 由 clip=null 表达，没有选中对象与选择了缺失素材不是同一状态。
// missing 可由显式场景或真实图片错误触发，loading/error 优先于封面判断。
// source 只是静态素材查看形态，必须有标题和明确的返回入口。
// onBack 由调用方注入，只通知返回，不在公共预览里猜测应跳到哪个路由。
// 两个实例可以共用相同 assets，但失败记忆和样板选择不能共用状态。
// currentTime 由调用方提供，不用计时器每秒推进来伪装播放成功。
// 不接收 onPlay、onSeek 或 onExport，因此不可能因参数遗漏而误启用处理。
// 长文件名保持 title，标题区采用省略，不把节目区域推到时间轴外。
// state 可由未来业务适配，但本轮没有请求、解码器或媒体事件订阅。
// assets 缺少引用时进入 missing，而不是错误使用第一张封面作为替代。
// 该接口仅用于渲染，不作为工程保存格式或跨进程类型。
// 切 source 不改素材选择与片段选择，只改变展示名称和时间范围。
// 真实文件来源仍由后续业务适配，本轮只允许现有静态图片契约。
interface ProgramPreviewProps {
  canvasEdit?: CanvasEdit;
  // 空画布的呈现由入口决定，状态样板仍需用文字解释正在演示哪一项。
  // 正式工作区则像未点亮的监视器，只保留黑色画布，不显示未选择的提示。
  // 该参数不影响加载、缺图和错误，不能用安静画布掩盖解码失败。
  // 默认message兼容原调用方，真实入口显式选择black，不靠路由字符串猜测。
  // 这只是同一预览容器的展示差异，不创建第二套播放器或媒体状态。
  emptyPresentation?: "message" | "black";
  // 标题行的局部动作由宿主注入，源查看与节目查看使用同一排版。
  // 例如窄窗面板入口需要占据真实宽度，不能悬浮在文件名上方。
  // 不传时保留静态样板原有标题，不让样板拥有真实会话业务。
  headerActions?: ReactNode;
  // 这是标题局部插槽，不接受整个工作区替换，素材行与时间线仍保留原有结构。
  // 返回按钮始终属于预览自身，宿主只补充与该标题同行的面板入口。
  // 静态节目、素材查看和真实单源都走这一处header，修复压字能同步生效。
  // 文件名使用专属previewName类，避免把EditorAction外层span误当文件名伸缩。
  // 这样英语按钮变宽时名称自动缩短，不需要维护另一组语言专属宽度。
  // 不设置固定像素占位，所以三栏模式隐藏临时入口后不会留下无用空白。
  // clip=null 是明确无选择，不自动找时间轴第一个片段顶替。
  // 引用存在但素材不存在时应是 missing，方便后续区分失联与空工程。
  clip: EditorPreviewClip | null;
  // 素材数组是查询来源，不包含当前素材高亮，也不被本组件排序或修改。
  // readonly 保留调用方共享静态资源对象的能力，避免不同样板互改数据。
  assets?: readonly EditorMediaAsset[];
  // 项目维度控制相框，帧率控制时间码，二者不取源缩略图的默认值。
  // 对同一封面传入竖屏项目时仍 contain，剩余黑边属于项目画布的一部分。
  project?: EditorPreviewProject;
  // currentTime 是工程秒数，即使在 source 形态也先接收工程位置。
  // source 显示时才减去片段起点，调用方不必维护第二份局部时间。
  currentTime?: number;
  // 显式状态优先于封面是否已存在，防止等待时显示旧图造成误解。
  // ready 仍需检查引用与封面，不能绕过真实图片错误回落。
  state?: "ready" | "loading" | "missing" | "error" | "black";
  // mode 是查看形态，不切换工程选择，也不改变文件是否能被读取。
  // program 保留工程总时长，source 只显示当前片段可查看的范围。
  mode?: "program" | "source";
  // 未提供返回回调时按钮原生禁用，不能用一个空函数假装可以返回。
  // 返回目标归宿主决定，所以这里没有硬编码路由或 window.history 操作。
  onBack?: () => void;
  live?: LivePreviewSource | null;
}

export interface LivePreviewSource {
  asset: EditorMediaAsset;
  surface: ReactNode;
  controls: ReactNode;
  state: "ready" | "loading" | "error";
  time: number;
  // 工程单段播放显示工程总长，素材查看仍使用源时长。
  duration?: number;
}
// 状态到文案的映射只承担显示，不根据翻译文字决定媒体是否可用。
// ready 的回落文案仅防御缺少图片的输入，不能把缺图误标为已完成。
// empty 对应未选择片段，black 对应明确黑场，二者不能共用含糊的“无内容”。
// audio 说明没有画面且播放未接通，不暗示音频文件损坏。
const PREVIEW_MESSAGES = { ready: "previewMissing", empty: "previewEmpty", loading: "previewLoading", missing: "previewMissing", error: "previewError", black: "previewBlack", audio: "previewAudio" } as const;
export { formatEditorTimecode } from "./editor-timecode";

// 原节目区三行布局保持：标题、可收缩画布、固定走带工具栏。
// 画布内另有项目比例框，源图片 contain，不让宽屏或窄屏截掉原图边缘。
// 所有状态占用同一画布槽位，错误或长文字不能改变工具栏的纵向位置。
// 图片错误按 src 记忆，只影响当前预览实例；换新封面地址可正常显示。
// loading/error 不挂图片，防止旧封面继续看起来像已完成的新预览。
// 整个面板只在 loading 标记 busy，错误和缺图不冒充仍在等待。
// 无片段、引用缺失、无封面、音频、黑场分别有准确提示。
// 音频不伪造一幅节目画面，也不显示假的播放进度或解码波形。
// 素材查看使用片段局部时间，节目查看使用工程时间，两者标题明确区分。
// 只在 source 显示返回按钮，没有回调时由共享按钮保持禁用。
// 播放、逐帧、适应和帧导出继续没有回调，原因明确静态预览边界。
// 标题中的文件名不参与查找，稳定 assetId 才是选中片段到封面的连接。
// 只有一个图片节点，缺图回落不会另开隐藏播放器或重复画面。
// asset.state 若为 loading/error，预览也不能把已存在的封面当作可用帧。
// currentTime 限制仅用于展示范围，不回写播放头或触发 seek。
// 当未选片段时仍显示项目总时长，当前时间回到起点。
// 无效项目宽高回落 16:9，避免样板非法参数撑坏布局。
// 时间码在 source 模式限制到片段长度，不展示负数局部时间。
// 正式音视频接入需要独立生命周期；这里没有需要取消的媒体会话。
// 独立样板的状态控制留在预览之外，默认编辑器不出现调试选项。
export function ProgramPreview({ clip, assets = DEMO_ASSETS, project = DEMO_PROJECT, currentTime = DEMO_PROJECT.currentTime, state = "ready", mode = "program", onBack, live = null, headerActions, canvasEdit, emptyPresentation = "message" }: ProgramPreviewProps) {
  // 查不到 asset 不能继续访问 cover，后面的状态解析负责说明缺失原因。
  // 显式 error/loading 比图片 onError 更高优先级，封面失败不改写业务输入。
  // failedCover 只保存当前实例见过的失败地址，不往素材对象添加全局坏图标记。
  // 同一实例切换到新 src 时与旧失败地址不同，正常图片可以自然恢复。
  // 切回原坏地址不无限重试，后续真实修复应由业务提供新的封面地址。
  // 没有选择时不借用上一张封面，避免用户误以为仍在编辑那个片段。
  // 音频的 null 封面不经过图片错误分支，视觉缺失和音频无画面分别提示。
  // source 的 duration 取片段实例范围，不把图片的 null 源时长转换成零秒。
  // 当前展示时间最多到总长，不允许传入的样例越界把时间码画到终点之外。
  // 这个限制仅影响显示数字，绝不调用定位播放器或回写项目时间。
  // ratio 需为有限正值，不能把除零结果塞给容器单位计算。
  // fallback 的 16:9 是无效输入的安全布局，不会覆盖调用方有效竖屏值。
  // 操作禁用原因集中为同一个静态预览边界，图标名称仍保留各自意图。
  // 原图片预览没有 video 节点，装配工具栏也不会启动解码或声音输出。
  // 区域仍标 R03，默认工作区只有一份；样板的重复实例在各自作用域里。
  // 各状态保留同样三行几何，切换时不需要测量后手动修改父布局高度。
  const { t } = useTranslation();
  const [failedCover, setFailedCover] = useState("");
  const asset = assets.find(item => item.id === clip?.assetId);
  const liveAsset = live?.asset;
  const assetState = (liveAsset ?? asset)?.state;
  const unavailable = assetState === "loading" || assetState === "error" || assetState === "missing" ? assetState : undefined;
  const staticMissing = !asset || (asset.kind !== "audio" && (!asset.cover || (typeof asset.cover === "string" ? asset.cover === failedCover : asset.cover.src === failedCover)));
  const liveState = live?.state;
  const displayState = state !== "ready" ? state : liveState ?? (!clip ? "empty" : unavailable ?? (staticMissing ? "missing" : asset.kind === "audio" ? "audio" : "ready"));
  const title = t(mode === "source" ? "toolBox.editorUi.sourcePreview" : "toolBox.editorUi.program");
  const duration = live?.duration ?? liveAsset?.duration ?? (mode === "source" && clip ? Math.max(0, clip.end - clip.start) : project.duration);
  // live传入的duration可切换工程总长和源长度，不能始终套用当前源duration。
  // source形态显示源内时钟；program形态显示工程书签，两者共用同一时间码外观。
  // 没有clip也可能有合法工程书签，例如用户定位在两段之间的黑场。
  // 因此这里不因clip为空强行归零，空样板要由它的调用方明确传零。
  // live.time已经由适配层决定时钟归属，不应再减一次clip.start。
  // 静态source仍接工程位置，所以仅这条路径需要换算成片段局部时间。
  // 显示夹限保护控制条，不能把夹限后的数值写回工程或声称完成媒体seek。
  // 黑场保留工程时间和项目fps，用户才能知道蓝线位于哪一段真实空隙。
  // 片段属性选择不在这个计算里更新，预览对象和编辑目标可以各自明确。
  // 固定宽度时间码使用共享格式化函数，不把30fps与源24fps混作同一来源。
  // 本页tabIndex=-1只供关闭紧凑面板后回落焦点，不增加正常Tab路径中的停靠项。
  // 主题切换只影响公共表面颜色，live媒体槽和静态图片都保持原来比例与内容。
  const time = live ? Math.min(Math.max(0, live.time), Math.max(0, duration)) : Math.min(Math.max(0, currentTime - (mode === "source" && clip ? clip.start : 0)), Math.max(0, duration));
  const ratio = project.width > 0 && project.height > 0 && Number.isFinite(project.width / project.height) ? project.width / project.height : 16 / 9;
  // empty与black仍保留各自data状态和时间码，只省略画布里的可见说明。
  // 像显示器的黑场与关机画面看上去相同，背后的工程时钟并不因此相同。
  // 有片段但引用丢失属于missing，不进入这条安静分支。
  // 真实源传入live时由其媒体槽接管，安静分支不吞媒体自身的错误反馈。
  // 不挂占位节点也就不会留下图标、隐藏的旧封面或会抢焦点的提示按钮。
  // 无障碍状态仍可从预览区域的状态属性与标题识别，时间码继续显示工程位置。
  // 背景覆盖只作用于frame内部，周围主题表面仍使用现有语义色。
  const quiet = emptyPresentation === "black" && (displayState === "empty" || displayState === "black");
  const reason = t("toolBox.editorUi.previewUnavailable");
  // 图片仍复用同一帧节点与错误回落，只有节目形态套片段构图；素材查看保持原图。
  const image = asset?.cover ? <Image src={asset.cover} alt={`${title} · ${asset.name}`} fill sizes="(min-width: 1280px) 60vw, 90vw" unoptimized={typeof asset.cover === "string"} className="object-contain" onError={() => setFailedCover(typeof asset.cover === "string" ? asset.cover : asset.cover?.src || "")} /> : null;
  const picture = clip && asset?.kind === "image" && mode === "program" ? <ClipCanvas clip={clip} asset={asset} project={project} edit={canvasEdit}>{image}</ClipCanvas> : image;
  // aria-label 命名的是当前查看形态，文件名通过图像 alt 和标题各自表达。
  // aria-busy 仅覆盖当前 R03，A 等待时不能让整个应用或 B 被标记忙碌。
  // 状态提示保留公共组件的 status/alert 语义，不用单独颜色表达错误。
  // 画布内占位可滚动，完整反馈不依赖被裁掉的 title 才能阅读。
  // 场景没有传入播放回调，因此禁用边界不依赖测试或运行环境是否安装 FFmpeg。
  return <section tabIndex={-1} data-editor-region="R03" data-editor-preview-state={displayState} data-editor-preview-clip={clip?.id} data-editor-preview-asset={liveAsset?.id ?? asset?.id} data-editor-preview-mode={mode} className={styles.previewPanel} aria-label={title} aria-busy={displayState === "loading" || undefined}>
    {/* R03：节目与素材查看共用标题栏，文件名省略但保留全名提示。 */}
    {/* 返回是查看层动作，不能把它绑到素材库选中或时间轴片段写入。 */}
    {/* 画布标题保持可见，长文件名只消费标题与返回之后剩余的宽度。 */}
    {/* R03：标题、返回、名称与局部动作同排分配空间，名称优先省略。 */}
    <header className={styles.previewHeading}><h2 className={styles.panelTitle}>{title}</h2>{mode === "source" && <EditorAction label={t("toolBox.editorUi.backToProgram")} onClick={onBack} />}<span className={styles.previewName} title={(liveAsset ?? asset)?.name}>{(liveAsset ?? asset)?.name}</span>{headerActions}</header>
    <div className={styles.previewSurface} data-editor-preview-surface>
      {/* surface 测量可用空间，frame 保留项目比例，图片在 frame 内完整放入。 */}
      {/* 占位也放进同一 frame，不能在缺图时把节目画布变成不同比例。 */}
      {/* Image 错误只记录 src，不回调外部选择，避免解码事件覆盖用户操作。 */}
      <div className={styles.previewFrame} style={{ width: `min(100cqw, calc(100cqh * ${ratio}))`, aspectRatio: ratio, ...(quiet ? { background: "#000" } : {}) }} data-editor-preview-frame>
        {quiet ? null : live ? live.surface : displayState === "ready" && asset?.cover ? picture : <EditorPlaceholder state={displayState === "audio" || displayState === "black" ? "empty" : displayState === "ready" ? "missing" : displayState} message={t(`toolBox.editorUi.${PREVIEW_MESSAGES[displayState]}`)} />}
      </div>
    </div>
    {/* 走带区只显示参数映射后的时间码，业务按钮没有播放或导出回调。 */}
    <div className={styles.transport}><span className={styles.timecode}><b>{formatEditorTimecode(time, (mode === "program" ? project.fps : liveAsset?.metadata?.fps) || project.fps)}</b><span>/</span>{formatEditorTimecode(duration, (mode === "program" ? project.fps : liveAsset?.metadata?.fps) || project.fps)}<small>{(mode === "program" ? project.fps : liveAsset?.metadata?.fps) || project.fps}fps</small></span><div className={styles.transportActions}><EditorAction icon={SkipBack} label={t("toolBox.editorUi.previousFrame")} disabledReason={reason} compact />{live ? live.controls : <EditorAction icon={Play} label={t("toolBox.editorUi.play")} disabledReason={reason} compact />}<EditorAction icon={SkipForward} label={t("toolBox.editorUi.nextFrame")} disabledReason={reason} compact /></div><EditorAction icon={ChevronDown} label={t("toolBox.editorUi.fit")} disabledReason={reason} /><EditorAction icon={Camera} label={t("toolBox.editorUi.exportFrame")} disabledReason={reason} /></div>
  </section>;
}

// 属性检查器实际实现只维护一份，旧导入路径继续转发同一组件。
export { ClipInspector } from "./editor-inspector";

"use client";

// UI-04 的独立节目样板复用同一个 ProgramPreview，不创建另一套预览容器。
// 场景只注入确定的演示参数，不读取文件或模拟媒体请求成功。
// 两个样板如同两台独立监看器，接同一份节目单仍各自选择查看哪一条。
// 对应机制是每个实例分别执行 hooks，片段 ID 和素材 ID 分开保存。
// 预览通过片段 assetId 查封面，素材高亮不参与这个查找。
// 控制区明确处于样板页，默认编辑器不出现场景开关。
// 加载、黑场和失败使用固定参数，不开计时器把等待推成成功。
// 原 UI-02 与 UI-03 样板保持原样，此文件只增加节目区验收入口。
import { useState } from "react";
import { useTranslation } from "@/i18n";
import { EditorAction } from "./editor-controls";
import { DEMO_ASSETS, DEMO_CLIPS, DEMO_PROJECT } from "./editor-demo";
import { MediaItem, ProgramPreview } from "./editor-panels";
import styles from "./editor.module.css";

// 场景名称映射到双语标签，不把内部状态字符串直接呈现给用户。
// ready 是静态封面，不能称为视频播放中或当前真实解码帧。
// missing 使用失联的 assetId，实际验证片段引用而不只手工传占位。
// broken 则给已有素材一个无法解码的封面，用于真实 onError 回落。
// 两种缺图来源分开，避免只验一种路径就声称完整覆盖缺失处理。
// empty 清除传入片段，不清除素材行高亮，能检查两类选择的独立性。
// long 只替换当前引用素材的名称，不改片段 ID 或封面。
// source 查看形态通过另一按钮切换，不混进状态联合。
// 这样 source 返回时能保留当前场景与所选片段。
// 状态样板无需网络访问，损坏地址只有固定坏字节。
// 场景列表保持固定顺序，测试按稳定 data 标记定位而不解析文案。
// 没有登记虚假的重试动作，恢复 ready 是用户显式切换演示场景。
const SCENARIOS = { ready: "previewReady", empty: "previewEmpty", loading: "loading", missing: "missing", error: "error", black: "previewBlack", broken: "previewBroken", long: "previewLong" } as const;
// 构建时固定坏图不依赖服务器 404，浏览器必须实际触发解码错误。
// 宽高描述仅满足静态图片展示契约，不伪造有效像素内容。
// 不使用用户文件路径，不把错误处理变成任意磁盘读取入口。
// 地址相同并不共用错误 state，ProgramPreview 每个实例自行记忆失败来源。
// 切回正常素材地址应恢复画面，而不是把整个实例永久标坏。
const BROKEN_COVER = { src: "data:image/webp;base64,YnJva2Vu", width: 1, height: 1 };

// 样板持有片段和素材两份 ID，任何一类操作都只更改自己的值。
// 片段按钮传引用 ID，不传文件名，改显示名称后仍可找到同一素材。
// 选片段只改变预览参数，不创建或删除 DEMO_CLIPS 中的记录。
// 当前工程时间从片段开始加两秒得到确定静态点，不运行真实时钟。
// source 模式将同一点映射成局部时间，返回节目后仍显示工程时间。
// 默认 clip-02 保留 12 秒与原图一致，音频/图片分别显示自己的静态状态。
// 音频片段不画假视频封面，ProgramPreview 会说明没有画面且播放未接通。
// 空场景保留素材区高亮，不能通过清空所有状态掩盖两者混用的问题。
// 缺引用场景使用未知 assetId，公共映射必须显示缺失而非第一个可用素材。
// 只在 broken 和 long 创建对象副本，原始共享数组不可修改。
// 损坏封面只替换当前片段引用的素材，不影响其他资源或另一个实例。
// 一个实例切场景时不改变另一个实例的模式、选择或图片失败记忆。
// 预览不依赖样板的片段按钮实现，正式宿主也注入同一份接口。
// 片段列表使用 EditorAction，沿用主题、焦点和 pressed 的公共外观。
// 素材列表使用 MediaItem，不手写另一套封面、长名省略或高亮边框。
// 下方素材行只负责样板高亮，未给它们传播放或时间线写入回调。
// 不创建工程 store，演示选择离开路由自然释放，也不写用户文档。
// mode 只属于查看状态，不给项目添加第二条输出或隐藏解码播放器。
// source 返回按钮使用明确回调，返回不会导航到其他应用页面。
// 标题的 A/B 只用于辨认实例，不能作为素材或片段的业务身份。
// 控件分组名称区分片段选择与预览状态，避免两组按钮被辅助阅读混淆。
// 五个片段共用同一个查找路径，测试应覆盖视频、图片和音频三个类型。
// 切换片段不应自动选中相应素材，反向切素材也不更新片段 ID。
// 素材行保留前三个视觉素材以便对比，音频类型通过片段按钮直接覆盖。
// 长名称场景在 source 和 program 都使用同一份标题结构，不各写 CSS。
// 场景 state=ready 不保证图片可解码，broken 必须走实际图片错误事件。
// 显式 loading/error 不挂图片，避免上一片段封面短暂冒充新预览成功。
// 没有真实异步任务，组件卸载时没有计时器、请求或文件句柄需要释放。
// 真实媒体接入后的取消与解码超时属于后续业务，不能由样板固定状态证明。
function PreviewSample({ id }: { id: string }) {
  // 这四份状态分别代表片段、素材、故障样例和查看形态，不共用一个 selected。
  // 选择音频片段后素材行仍可高亮图片，正是两类选择独立的合法状态。
  // 空场景只传 null 给预览，底部素材选择不会为了配合空态被清除。
  // 从 source 返回只改变 source 布尔值，故障样例和片段 ID 均保留。
  // 选择片段的按钮标签从同一 DEMO_ASSETS 查名称，不另写同名字符串表。
  // 片段引用缺失时标签回落到 assetId，不能静默显示其他素材的名称。
  // long 场景替换的是显示名称，不使用超长名称作为 React key。
  // 因此切换该场景不会创建新素材身份或丢失原来的片段选择。
  // 切 broken 后再选别的片段，会给新的引用素材注入坏封面，场景语义保持一致。
  // 程序没有导入文件动作，所以所有素材数量与片段数量始终确定。
  // 样板可组合场景与媒体类型，例如音频 error 表示明确失败而非默认无画面。
  // 这些组合仍通过公共 ProgramPreview 的优先级处理，不在样板另写占位。
  const { t } = useTranslation();
  const [selectedClip, setSelectedClip] = useState<string>("clip-02");
  const [selectedAsset, setSelectedAsset] = useState("scene-02");
  const [scenario, setScenario] = useState<keyof typeof SCENARIOS>("ready");
  const [source, setSource] = useState(false);
  const clip = DEMO_CLIPS.find(item => item.id === selectedClip) ?? null;
  // B 使用竖屏 24fps，证明画布比例与帧率来自参数，而非写死为默认 16:9/30fps。
  // B 的静态时间多四分之一秒，帧尾应为 06；源封面仍 contain，不裁切成竖屏。
  // A 保留确认稿的横屏 30fps 与整数秒，默认工作区不受样板参数影响。
  const project = id === "B" ? { ...DEMO_PROJECT, width: 1080, height: 1920, fps: 24 } : DEMO_PROJECT;
  const assets = DEMO_ASSETS.map(asset => asset.id !== clip?.assetId ? asset : { ...asset, cover: scenario === "broken" ? BROKEN_COVER : asset.cover, name: scenario === "long" ? "scene_with_a_very_long_filename_1920x1080_spring_landscape_final_revision_2026_storyboard_reference_colour_corrected_preview_take_00000042.mp4" : asset.name });
  const state = scenario === "loading" || scenario === "error" || scenario === "black" ? scenario : "ready";
  return <section data-editor-preview-sample={id} className={`${styles.sampleInstance} ${styles.previewSample}`}>
    <h2>{t("toolBox.editorUi.program")} · {id}</h2>
    {/* 片段控制：这里只注入选中 ID，不编辑轨道、属性或源素材选择。 */}
    <div role="group" aria-label={t("toolBox.editorUi.previewClipChoice")} data-preview-clip-choices className={styles.sampleActions}>{DEMO_CLIPS.map(item => <EditorAction key={item.id} label={DEMO_ASSETS.find(asset => asset.id === item.assetId)?.name ?? item.assetId} pressed={selectedClip === item.id} onClick={() => setSelectedClip(item.id)} />)}</div>
    {/* 状态控制：显式样例留在预览之外，不污染默认节目区布局。 */}
    <div role="group" aria-label={t("toolBox.editorUi.previewStateChoice")} data-preview-state-choices className={styles.sampleActions}>{(Object.keys(SCENARIOS) as (keyof typeof SCENARIOS)[]).map(value => <span key={value} data-preview-scenario={value}><EditorAction label={t(`toolBox.editorUi.${SCENARIOS[value]}`)} pressed={scenario === value} onClick={() => setScenario(value)} /></span>)}<EditorAction label={t("toolBox.editorUi.sourcePreview")} pressed={source} onClick={() => setSource(!source)} /></div>
    {/* 空样板的时间由样板归零；正式黑场仍允许保留独立工程书签。 */}
    <ProgramPreview clip={scenario === "empty" ? null : scenario === "missing" && clip ? { ...clip, assetId: "missing-asset" } : clip} assets={assets} project={project} currentTime={scenario !== "empty" && clip ? clip.start + 2 + (id === "B" ? .25 : 0) : 0} state={state} mode={source ? "source" : "program"} onBack={() => setSource(false)} />
    {/* 素材控制：共用行外壳，但不拿此处高亮决定上方节目画面。 */}
    <ul className={styles.previewSampleMedia}>{DEMO_ASSETS.slice(0, 3).map(asset => <MediaItem key={asset.id} asset={asset} selected={selectedAsset === asset.id} onSelect={() => setSelectedAsset(asset.id)} />)}</ul>
  </section>;
}

// 公共入口追加在 UI-02/UI-03 样板后，不重建路由或第二份 AppShell。
// 同一组件实例化两次，能发现模块级选中值或图片错误 state 串用。
// sampleGrid 已有窄列重排，无需复制一套移动版节目样板。
// 标题由当前 i18n 决议，主题仍沿用现有原生媒体查询信号。
// 两种主题呈现同一份 DOM 与选择值，不依靠重新挂载换皮肤。
// 样板 page 已说明演示边界，这里不重复弹窗或假成功提示。
// UI-04 验收停在此处，不因样板能切片段就开启默认时间轴拖拽或属性提交。
// 此处不传任意 className 给公共预览，稳定几何仍由公共 CSS Module 管理。
export function EditorPreviewSamples() {
  const { t } = useTranslation();
  return <section><h2>{t("toolBox.editorUi.previewSamples")}</h2><div className={styles.sampleGrid}><PreviewSample id="A" /><PreviewSample id="B" /></div></section>;
}

/** 属性展示模型：从片段、项目和明确覆盖值组合字段，不把样例参数写进正式工程。 */
import type { EditorMediaAsset, EditorPreviewProject } from "./editor-panels";

// 本模块接收的是检查器目标，不把素材库的一行直接当作工程片段。
// 同一素材在时间线上可以安排两次，两次的id和安排时长都可能不同。
// asset只提供媒体类别和显示信息；duration由该次安排的end-start取得。
// 因此改变素材列表的高亮不应该重新生成这里的目标集合。
// 正式宿主只在片段选中变化后适配目标，样板则从演示选择生成目标。
// 数据适配放在边界，可以让检查器不认识导入批次、拖动载荷和文件系统。
// 这里的类型没有DOM引用，也没有播放器实例，读取默认值不会开始解码。
// 默认值是展示约定，不是已应用滤镜或已完成转码的证明。
// 后续接入真实效果时，需要另行确定效果存储和预览提交契约。
// 不能因为输入框已能编辑，就把样板覆盖值搬到正式工程当作完成效果。

// values 只保存对象已经确认的覆盖值，没有值时读取项目约定的默认值。
// 就像表格中留空表示沿用模板，不能把模板数值伪装成已经处理过的效果。
// 正式片段的五种画面变换已由宿主适配为values，其他效果仍只读默认值。
// 样板可以持有自己的覆盖值，验证输入而不改变真实片段或源文件。
export type PropertyKey = "scale" | "x" | "y" | "rotation" | "opacity" | "speed" | "volume" | "fadeIn" | "fadeOut" | "duration";
export type PropertyValues = Record<PropertyKey, number>;
// 完整PropertyValues适合表示一份默认参数，目标上的Partial只记录覆盖部分。
// 例如只改缩放的对象无需复制一份项目中心，切换项目尺寸时仍能读到正确默认位置。
// undefined代表没有覆盖；零是有意义的值，例如完全透明或没有淡入。
// 后面用空值合并而不用逻辑或，避免把合法零误替换为默认值。
// values不能存字符串“—”，混合状态由比较过程单独报告。
// 类型允许未来调用方带确认值，但这个模块不负责给未知外部JSON做安全校验。
// 当前样板写入来自同一个数值字段的有限数字，正式目标不传效果覆盖。
// 片段身份使用id，不用文件名；重名素材不会互相覆盖检查器状态。
export interface InspectorTarget { id: string; asset: EditorMediaAsset; duration: number; values?: Partial<PropertyValues>; }
export interface PropertyField { key: PropertyKey; unit: string; min: number; max: number; precision: number; }

// 数值精度与单位在字段定义处共用，视频与图片不各写一套 X/Y 输入规则。
// 位置以项目像素表达画面中心，默认中心由项目尺寸决定，与预览 CSS 尺寸无关。
// 限制只在提交时检查，输入负号、小数点和第一位数字都属于合法草稿过程。
// 时长上限不是源探测事实；图片样板允许设置安排长度，正式工作区仍禁止编辑。
// 淡入淡出上限随后按最短选中片段限制，不能只用一个固定30秒样例上限。
const FIELDS: Record<PropertyKey, PropertyField> = {
  // 正式构图以100为contain基础适配尺寸，最小值大于零，避免退化平面。
  // 放大只改变单源显示几何，不提高解码分辨率；过大部分由项目边界裁切。
  // 两位精度是提交显示规则，不是在每个按键时把草稿强行补成两位。
  scale: { key: "scale", unit: "%", min: .01, max: 10000, precision: 2 },
  // X以项目左边为零；允许负位置，为将来的画面移出画布保留表达能力。
  // 单位px指项目像素，预览容器宽度和系统DPR都不能参与默认坐标计算。
  // Y同理采用项目顶部为零，默认画面中心在项目高度的一半。
  // 正负十万是有限输入边界，防止无穷数进入以后的位置计算。
  x: { key: "x", unit: "px", min: -100000, max: 100000, precision: 2 },
  y: { key: "y", unit: "px", min: -100000, max: 100000, precision: 2 },
  // 旋转保留累计角度，输入360不被悄悄改写成零，当前仅验证表单契约。
  // 不透明度零与一百都有效，分别表示透明和完整可见的参数含义。
  // 样板改变这些数字不改变视频标签的CSS，也不声称正在执行画面变换。
  rotation: { key: "rotation", unit: "°", min: -36000, max: 36000, precision: 2 },
  opacity: { key: "opacity", unit: "%", min: 0, max: 100, precision: 1 },
  // 速度用倍率显示，默认一倍；不能把百分数100直接交给倍率字段。
  // 音量可表达超过原声的目标值，实际限幅和混音留给未来音频处理任务。
  // 这两项的最大值不同，不能仅因都是数字输入就共用一套范围。
  speed: { key: "speed", unit: "×", min: .1, max: 10, precision: 2 },
  volume: { key: "volume", unit: "%", min: 0, max: 400, precision: 1 },
  // Infinity只在配置中充当待收窄上界，真实输入仍必须是有限数字。
  // 后面的选择适配会把淡入淡出最大值换成最短安排长度。
  // 淡入和淡出各自不能长过片段；两者之和的效果策略尚未接入。
  // 不在这里凭空实施交叉淡化或调整别的片段来满足某个值。
  fadeIn: { key: "fadeIn", unit: "s", min: 0, max: Infinity, precision: 2 },
  fadeOut: { key: "fadeOut", unit: "s", min: 0, max: Infinity, precision: 2 },
  // 图片本身没有源播放长度，时长字段指它在工程中被安排多久。
  // 一天上限属于样板输入保护，不会反向写成图片探测的媒体事实。
  // 视频源时长不会复用这个可编辑字段，避免让UI看似具备修剪能力。
  duration: { key: "duration", unit: "s", min: .01, max: 86400, precision: 2 },
};
// 共有字段取交集：视频和图片能共同调整变换，视频和音频只能共同展示淡入淡出。
// 不取并集，否则图片会出现音量、音频会出现没有意义的画面位置。
// 分离音轨的 asset.kind 由正式宿主适配成 audio，不由文件扩展名猜测。
const KIND_FIELDS = {
  video: ["scale", "x", "y", "rotation", "opacity", "speed", "fadeIn", "fadeOut"],
  image: ["scale", "x", "y", "rotation", "opacity", "duration"],
  audio: ["volume", "fadeIn", "fadeOut"],
} satisfies Record<EditorMediaAsset["kind"], PropertyKey[]>;

// 交集的顺序沿用首种媒体的字段顺序，布局不会因为选中顺序随机打散分组。
// 两视频能共同展示速度和画面变换，因为它们属于相同有效字段集合。
// 视频加图片只能展示画面变换，视频速度不适用于静态图片。
// 视频加音频只保留淡入淡出，不给音频显示画面中心。
// 图片加音频没有共同字段，外壳会显示没有共有属性的说明。
// 三种类型一起选也可能没有共有字段，空交集不是探测失败。
// 这里不按文件后缀分类，分离出的音轨仍可能引用原来的mp4文件。
// 当前适配后的asset.kind是有效依据，避免音轨意外出现缩放字段。
// satisfies检查配置覆盖每种媒体，但不会把数组中的字段键扩大成任意字符串。
// 新媒体类型若要加入，需要显式决定字段集合，而非默认借视频整套属性。

// 默认值来自工程坐标和对象安排长度，不读取另一个对象的草稿。
// 源视频帧率不改变项目中心，移动片段也不改变画面 X/Y。
// 覆盖值最后合并，明确区分默认来源与样板已确认值。
// 本函数没有写入、解码或保存副作用，可供重置与显示共同调用。
export function propertyDefaults(target: InspectorTarget, project: EditorPreviewProject): PropertyValues {
  return { scale: 100, x: project.width / 2, y: project.height / 2, rotation: 0, opacity: 100, speed: 1, volume: 100, fadeIn: 0, fadeOut: 0, duration: target.duration };
}

// 1920×1080工程中心为960、540；1080×1920工程应改为540、960。
// 这两个例子是项目坐标，不能依据画布在屏幕上的600px宽来返回300。
// 默认duration来自目标，不来自整个工程最大end，十秒图片不是三十秒项目。
// 重置调用这个函数逐个目标计算，所以不同长度对象可以恢复不同默认时长。
// 重置后的混合显示仍有可能存在，这是来源不同而非重置失败。
// 工程没有选中片段时不应创建虚构target来凑这些参数。

// 混合判断比较确认后的数值，不比较格式化文本，1和1.00视为同一数值。
// 返回首项只作为字段代表值，mixed=true 时输入必须显示横线而不是首项。
// 空选择不会到这里，外层用项目参数视图表达没有片段的状态。
// 不把混合值写成NaN，避免校验、精度格式化和范围组件收到无效数字。
export function propertyValue(targets: readonly InspectorTarget[], project: EditorPreviewProject, key: PropertyKey) {
  const values = targets.map(target => target.values?.[key] ?? propertyDefaults(target, project)[key]);
  return { value: values[0] ?? 0, mixed: values.some(value => value !== values[0]) };
}

// 比较后的代表值和mixed是两个独立信息，数值100与混合的首项100不能等价。
// 公共输入框收到mixed后保留空文本和横线占位，不让用户误读首项为统一结果。
// 主动输入100仍须通知整个选择集合，不能因为代表值也为100而跳过其他对象。
// 尚未输入直接失焦则没有统一意图，不应替全部对象填入零。
// 浮点比较针对已确认数值；显示精度不参与比较，避免格式化文本隐藏真实差异。
// 本函数只读目标，不会替任何对象补写默认参数，调用多次仍没有数据迁移副作用。

// 淡入淡出上限取最短片段，统一输入不能超过其中任意一个安排。
// 字段定义复制后再调整，不能污染下一个样板或另一类型的最大值。
// 这里返回展示与校验参数，不负责改变源时长或实际音视频处理。
export function inspectorFields(targets: readonly InspectorTarget[]): PropertyField[] {
  if (!targets.length) return [];
  const keys = KIND_FIELDS[targets[0].asset.kind] as PropertyKey[];
  return keys.filter(key => targets.every(target => (KIND_FIELDS[target.asset.kind] as PropertyKey[]).includes(key)))
    .map(key => ({ ...FIELDS[key], max: key === "fadeIn" || key === "fadeOut" ? Math.min(...targets.map(target => target.duration)) : FIELDS[key].max }));
}

// 例如选中三秒和八秒两段，统一淡入上界是三秒，而不是八秒或工程总长。
// 拷贝定义后换max，保护模块常量不被这一轮多选污染。
// 如果直接原地改FIELDS，随后单选四十秒对象也会残留上次三秒上限。
// 返回空数组有两个合法原因：没有目标，或所有目标没有公共字段。
// 两种文案在检查器外壳按选择数量区分，不让纯模型携带翻译或显示组件。
// 结果保留key，UI以key定位回调，不能以翻译后的标签猜测效果种类。

// 分组只决定字段排列，不让 UI 根据翻译文字推断写入哪种业务。
// 两类淡入淡出共用同一组键，目标与写入回调仍由检查器调用方拥有。
export function propertyGroup(key: PropertyKey) {
  return key === "fadeIn" || key === "fadeOut" ? "fades" : key === "speed" ? "playback" : key === "volume" ? "volume" : key === "duration" ? "duration" : "transform";
}

