    // lane不存在时不强行设置另一个容器，仍清理本次恢复意图以免迟到重放。
    // 这个方法没有setState，layoutEffect每次调用也不会制造渲染循环。
    // restore与zoom共用range，不从标尺文字解析秒数，避免格式化造成精度损失。
    const lane = scroller.current?.querySelector<HTMLElement>("[data-editor-region=R07]");
