// 松手后工程确认值接管，Escape则移除候选，宿主不做反向位移。
// 属性提交与画布提交都调用timeline.transform，范围和锁规则只有一份。
// 同一个媒体节点仅因style变化重新排版，不因构图值变化换key。
// 保留实际video是本轮验收重点，不能在拖动时用封面替换它。
// 预览尺寸变化只调整百分比渲染，项目像素数据不回写为屏幕尺寸。
// 紧凑面板开合可以改变frame，但不应改变已确认构图。
// 隐藏属性面板时工程仍保留五个值，下次打开读取同一片段记录。
// 速度和淡入淡出字段不在editable清单内，传了onCommit也不会误启用。
// 音轨不传画面变换目标，画面参数不能被用于调音量。
// 项目宽高是工程配置常量，不由横竖素材切换自动改写。
// 默认中心是工程中心，竖视频两侧黑场属于项目留边。
// 裁切由ClipCanvas内容层执行，宿主不把画面拖动限制在可见边界。
// 导出与保存仍未接入，本轮画面变化仅存在当前页面工程会话。
  const currentTime = timeline.currentTime;
  // 两种预览互斥显示，但共用同一组窄窗入口，不复制按钮体系。
  // 动作放在标题流内，文件名会让出实际宽度，英文标签也无需猜宽。
  // 入口回调由workspace提供；媒体播放与面板开合没有共享业务状态。
// 窄窗入口原先绝对定位在右上，会与长文件名占用同一块空间。
// 现在让它们参与标题行排版，文件名可压缩，按钮不覆盖文字。
// ProgramPreview和LiveSourcePreview接收同一个React片段，返回节目不更换控件外观。
// 这只是两种互斥预览中的插槽复用，不会把两个播放器一起隐藏挂载。
// 静态工程也注入相同布局入口，但不获得正式会话的导入或工程编辑回调。
// 素材与属性入口只控制显示，不启用面板中原本未接通的业务字段。
// 开合入口不会清空当前片段，也不会替用户切换素材高亮。
// 此处不按文件名长度估算宽度，中文和英文都交给真实flex几何处理。
// 标题区的滚动归属仍在共享预览容器，不创建独立横向滚动条。
// 外层nav开合改变可用宽度时，标题行会随容器重新分配空间。
  // 外部文件像送到货架的新包裹，只在真正松手时进入统一导入流程。
  // 内部片段拖动像挪动安排表，不是重新搬运视频文件，不能触发导入提示。
  // 不再记录整页dragging布尔值：子轨道会截住事件，外层未必收到对应的离开通知。
  // 取消遮罩后没有需要配对清除的视觉状态，Escape或离开窗口也不会留下提示。
  // dragOver只允许外部Files落下，不读取其中的路径或提前调用探测。
  // 路径仍在drop时经preload解析，不使用浏览器File.path或Node文件接口。
  // 真实导入的加载与错误继续由素材行表达，不靠全区覆盖模拟处理中。
  // 已有媒体节点不会因内部拖过轨道而卸载，播放时钟和当前画面因此保持原归属。
  function acceptDrop(event: DragEvent<HTMLDivElement>) {
    // 只有Files走既有导入链；内部身份拖放由时间线处理，不能误报非法文件。
    // 外部文件即使落在V1也只入库，后续明确添加才会产生片段。
    if (!event.dataTransfer.types.includes("Files")) return;
    event.preventDefault();
    const paths = Array.from(event.dataTransfer.files).map(file => window.electronAPI?.getPathForFile(file) ?? "");
    if (!paths.length) paths.push("");
    void live.startImport(paths);
  }
  return <div data-video-editor-ui="LIVE-02" data-live-video-session className={styles.host} onDragOver={event => { if (event.dataTransfer.types.includes("Files")) event.preventDefault(); }} onDrop={acceptDrop}><EditorWorkspace project={project} clips={timeline.clips} assets={live.assets} currentTime={currentTime} timeline={timeline.interaction} onImport={() => { void live.startImport(); }} busy={live.importBusy} onCancelImport={live.cancelImport}>
    {headerActions => <>

      {/* 素材区：正式会话传真实数组，样板组件默认数据保持独立。 */}
      <MediaPanel assets={live.assets} selectedId={live.selectedAssetId} onSelect={live.selectAsset} onAssetDragStart={(event, id) => timeline.interaction.start(event, "asset", id)} onAssetDragEnd={timeline.interaction.cancel} onAddToTimeline={timeline.addAsset} onImport={() => { void live.startImport(); }} onCancelImport={live.cancelImport} importBusy={live.importBusy} importNotice={live.importNotice} />
      {/* 素材预览只读源媒体时钟，返回节目后不改时间线片段选择。 */}
      {previewAsset ? <LiveSourcePreview key={live.sourceVisible ? previewAsset.id : timeline.playbackClip?.id} asset={previewAsset} clip={live.sourceVisible ? undefined : timeline.playbackClip ?? undefined} transport={live.sourceVisible ? undefined : { time: currentTime, version: timeline.seekVersion, onTime: timeline.reportTime }} project={project} onBack={() => { live.returnToProgram(); timeline.closePreview(); }} headerActions={headerActions} canvasEdit={!live.sourceVisible && timeline.playbackClip && !timeline.playbackClip.audioOnly ? transform.canvas(timeline.playbackClip) : undefined} /> : <ProgramPreview clip={null} emptyPresentation="black" state={timeline.clips.length ? "black" : "ready"} assets={live.assets} project={project} currentTime={currentTime} headerActions={headerActions} />}
      <ClipInspector project={project} live editableKeys={transform.editable} locked={transform.locked} onCommit={transform.commitField} onReset={transform.reset} targets={timeline.selectedClip && clipAsset ? [{ id: timeline.selectedClip.id, asset: clipAsset, duration: timeline.selectedClip.end - timeline.selectedClip.start, values: transform.value(timeline.selectedClip) }] : []} />
      {/* 片段菜单：一次只绑定当前工程的实例，关闭或切页由公共外壳清理。 */}
      {timeline.menu.anchor && <LiveClipMenu anchor={timeline.menu.anchor} clip={timeline.clips.find(clip => clip.id === timeline.menu.anchor?.id)} asset={live.assets.find(asset => asset.id === timeline.clips.find(clip => clip.id === timeline.menu.anchor?.id)?.assetId)} onClose={timeline.menu.close} onAction={timeline.menu.perform} />}
  </>}</EditorWorkspace></div>;
}

