  smoke.assertBuildFresh({ app });
  nativeTheme.themeSource = "light";
  const horizontal = makeVideo("landscape-audio.mp4", "640x360", 30, true);
  const vertical = makeVideo("portrait-silent.mp4", "360x640", 24, false);
