    else await verifyExplorerDrop();
    console.log("LIVE_MEDIA_ROOT", root);
  } finally { win.destroy(); }
  smoke.finish({ app, ok: smoke.allPassed() });
}

main().catch(error => { console.error(error); if (win && !win.isDestroyed()) win.destroy(); smoke.finish({ app, ok: false, error }); });

