/** 属性检查器的公开DOM回归；复用现有Electron窗口和样板路由，不模拟媒体效果。 */
const fs = require("node:fs"), path = require("node:path");
// 本文件只验证属性UI，不把样板的局部覆盖值当成工程效果已经生效。
// 窗口、协议、preload和静态产物检查由主套件建立，不在helper复制启动流程。
// 所有选择都经过公开按钮，不能直接改React状态或调用内部commit函数。
// 观察到input变字还不够，切对象后再读值，才能区分草稿与确认值。
// A/B是同组件的两个独立实例，B用于反证错误、选择和覆盖值没有串用。
// 样板有确定的五项素材，测试用固定名字定位，避免按页面第一个input误点。
// 真正文件导入和媒体解码仍由LIVE回归负责，本组没有创建视频源。
// 若这里失败，外层harness保留非零退出码，截图不能把失败覆盖成通过。
// 中文标签是此隔离游客文档的当前语言，不从生产LABELS导入预期字段。
// 这样生产误把旋转标题映射到缩放时，测试不会跟着相同配置一起误过。
// 数值比较看格式化后的确认显示，同时结合类型组合检查是否存在错误字段。
// Enter、Escape和input由DOM派发，是自动事件证据，不能标成人工键盘操作。
// focus与blur发生在真实Chromium文档内，但不需要抢用户系统桌面焦点。
// 外层显式启用焦点模拟，避免隐藏窗口不产生focusout而误把草稿当确认结果。
// 每次查找限定 A/B，防止总取第一个实例掩盖状态串用。
// label来自已确认的中文界面，测试不读取生产字段配置来自证。
const scope = id => `[data-inspector-sample=${id}]`;
const field = (id, label) => `${scope(id)} label`;

// 以标签文字定位真实输入，不依赖CSS哈希，也不访问React私有状态。
// 模拟事件只作为UI自动化证据，不能当成人工键盘或媒体处理证明。
// 焦点和失焦真实发生在Chromium文档内，Enter/Escape走公共字段处理。
async function edit(ctx, label, text, key = "Enter") {
  // 使用原生value setter通知React受控输入，直接改HTML属性不能代表用户输入。
  // input事件冒泡到公共字段，产品自己的onChange负责保存临时字符串。
  // 输入字符串可以是负号、空白或错误文本，不能在测试里先替产品矫正。
  // 键事件与input分两次调用，让React先提交草稿，再执行确认或取消。
  // 短等待只让当前UI提交，没有循环重试直到碰巧读到预期值。
  // 每次先focus目标字段，使后续document.activeElement确实是本次输入。
  // label限定到A，B作为观察对照，不应被编辑helper顺带改写。
  // key为Tab时只保留草稿，真正失焦由下一步.focus触发，不用假blur代替。
  // 这是因为合成Tab不会自动执行浏览器默认焦点跳转，测试须说明证据边界。
  // onKeyDown仍处理Enter/Escape，不能直接调用onCommit跳过范围校验。
  await ctx.run(`(()=>{const e=[...document.querySelectorAll('${field("A", label)}')].find(e=>e.firstElementChild.textContent===${JSON.stringify(label)}).querySelector('input');e.focus();Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,${JSON.stringify(text)});e.dispatchEvent(new Event('input',{bubbles:true}))})()`);
  await ctx.delay(60);
  await ctx.run(`document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:${JSON.stringify(key)},bubbles:true}))`);
  await ctx.delay(60);
}
// 取值是观察，不把输入value改成预期结果；确认来源仍是产品回调后的显示。
// 同一标签在不同实例可能不同，域参数使A的修改不能误读成B也已生效。
function value(ctx, id, label) {
  // label找不到返回undefined，类型字段不应出现时可以明确断言不存在。
  // 找到但值为空会返回空串，与字段缺失不同，混合值要另读placeholder。
  // 不将读值转Number，否则空串会变成零，掩盖混合状态误提交问题。
  // 这里不读取data中的预设值，而读用户实际看到的受控input.value。
  // 调用者可比较80.00与80，发现提交后的精度格式化是否执行。
  // 同一个标签必须带域参数，不能用全局querySelector把A当作B读取。
  return ctx.run(`(()=>{const e=[...document.querySelectorAll('${field(id, label)}')].find(e=>e.firstElementChild.textContent===${JSON.stringify(label)});return e?.querySelector('input')?.value})()`);
}
async function choose(ctx, label) {
  // 选择用原按钮click，样板根据稳定ID计算selected，检查器重新组合目标。
  // helper不直接拼一个targets数组传给组件，所以能覆盖公开调用链。
  // 选择完成后有界等待本地提交，不执行重新加载来清掉旧字段状态。
  // 切换类型后若残留旧字段，下方查询会明确失败而非读取旧缓存。
  // 这里不滚动画面或截取像素，行为断言与截图记录分别完成。
  await ctx.run(`document.querySelector('${scope("A")} button[aria-label=${JSON.stringify(label)}]').click()`);
  await ctx.delay(80);
}

// 混合值先验证横线，再统一为80；80恰等于第二项原值，用来发现仅按首项比较的漏提交。
// 切回各对象读确认值，不能仅看当前混合框的临时文本就宣称两项都已改变。
// A/B从相同演示数据开始，B保持100说明共享组件没有共享覆盖值。
async function checkMixed(ctx) {
  // 初始首视频缩放100，第二视频80；两个对象并非相同默认参数的重复副本。
  // 切混合后先看横线，防止控件直接显示首项100造成统一值假象。
  // 输入80后第一对象应改变，第二对象本来就是80也必须继续保持。
  // 再逐个切回单选，可以发现只改临时代表值而没更新选择集合的实现。
  // B始终保留初始100，反证局部覆盖没有写进DEMO_ASSETS或模块级共享缓存。
  // 第一对象的确认值在前一组已重置为100，条件不是依赖刚输入的草稿。
  // 选择第二对象不会清第一对象的覆盖，否则切回时会恢复100被后续测试发现。
  // 这里验证统一数值，不声明完成多选时间线操作或批量媒体处理。
  // 属性目标数量来自样板选择，正式时间线当前仍是独立单选。
  // 本组不读取React内部state，只通过同一个ClipInspector的可见字段反查结果。
  // 混合的placeholder是“—”，不是输入value，不能把符号交Number解析。
  // 等于代表值仍回调的边界也由公共控件语义保障，不能简单用value相等早退。
  await choose(ctx, "多选混合");
  ctx.smoke.check("UI05: mixed selection displays a dash instead of the first value", await ctx.run(`document.querySelector('${scope("A")} input[data-editor-mixed]').placeholder==='—'`));
  await edit(ctx, "缩放", "80");
  await choose(ctx, "scene_01.mp4");
  ctx.smoke.check("UI05: mixed commit updates the first selected target only in A", await value(ctx, "A", "缩放") === "80.00" && await value(ctx, "B", "缩放") === "100.00");
  await choose(ctx, "scene_02.mp4");
  ctx.smoke.check("UI05: the other selected target receives the same confirmed value", await value(ctx, "A", "缩放") === "80.00");
}

// 类型切换检查的是字段交集，不以文件名后缀推断应显示的字段。
// 音频不能有画面变换，图片不能有视频速度；无选择展示项目事实。
// 重置与折叠分别验证值和布局，不用一条模糊“无异常”替代两个职责。
async function checkTypes(ctx) {
  // 音频测试同时要求音量存在、缩放缺失，不能只检查标题从视频变成音频。
  // 淡入提交0.25，用非整数覆盖共用字段的精度处理。
  // 切图片要求十秒安排长度，不把图片没有duration当作零秒。
  // 图片没有speed，能反证之前视频字段没有因同组件复用而残留。
  // 无选择必须没有input，不能只在旧表单上盖一句“未选择”。
  // 项目分辨率来自样板项目1920×1080，不能显示素材的缩略图尺寸。
  // 无选择时保留项目总长，不代表清空工程片段。
  // 音频淡入只改变该目标的样板确认值，不生成音频文件或波形。
  // 本组不检查真实声音变化，因为正式效果尚未接入。
  // 当前source素材是固定演示数据，不需要联网或扫描用户磁盘。
  await choose(ctx, "voice_01.wav");
  ctx.smoke.check("UI05: audio exposes volume and fades, with no visual transform", await value(ctx, "A", "音量") === "100.0" && await value(ctx, "A", "缩放") === undefined);
  await edit(ctx, "淡入", "0.25");
  await choose(ctx, "bg_01.png");
  ctx.smoke.check("UI05: image exposes its arranged duration, not speed or volume", await value(ctx, "A", "时长") === "10.00" && await value(ctx, "A", "速度") === undefined);
  await choose(ctx, "无选择");
  // 此时先前已确认过音频淡入和图片选择，空态还可反证旧字段没有残留。
  // dl中的项目尺寸是工程事实，不是“无选择”按钮写入的一份新项目配置。
  // 输入节点数量为零比disabled为true更严格，空选择不应显示虚构视频参数。
  // 空选择不删除targets，随后回到scene_01仍能测试原先的覆盖与重置。
  // B保持自己的单视频选择，A的无选择不会把B也切成项目事实面板。
  ctx.smoke.check("UI05: no selection shows project resolution and fps without stale fields", await ctx.run(`document.querySelector('${scope("A")} [data-editor-region=R04]').textContent.includes('1920 × 1080')&&!document.querySelector('${scope("A")} input')`));
}

// 组合按钮只传目标集合，交集由正式检查器计算；预期字段由测试独立列出。
// 画面与音频无交集时必须给出明确空态，不能随机显示首项整张表。
// 视频和图片共有变换，不应把时长或速度借给另一个类型。
async function checkCombinations(ctx) {
  // 0-2对应视频加图片，预期只保留五个画面字段。
  // 0-3对应视频加音频，预期只保留淡入和淡出。
  // 2-3对应图片加音频，没有公共属性，仍应保留选中对象数量。
  // 0-2-3把三类一起传入，交集为空不能退化成第一视频整张表。
  // 预期标签数组独立写出，不调用生产inspectorFields给自己生成答案。
  // 比较有序标签集合，既发现漏字段，也发现多出无效字段或重复分组。
  // 每次操作仍通过样板组合按钮，组件本身负责计算交集而不是测试筛选。
  // 组合循环不重建页面，上一组合的字段不能靠路由重载被清除。
  // 第一轮reset先恢复100，为后面的“确认值不变”反例建立准确前提。
  // 随后输入invalid并按Enter，错误草稿留在本地，确认值仍为100。
  // 第二次reset写回同一个100，旧value没有变化，恰能发现只靠value同步的漏洞。
  // 正确实现须同时清除aria-invalid与非法文本，单改红框不算恢复。
  // 不通过Escape清掉错误后再测reset，那样无法证明reset本身有效。
  // 折叠使用真实组标题按钮，B的aria-expanded必须保持true。
  // 这条只检查公开折叠语义，原公共控件回归还检查inert与字段可见范围。
  // 最后恢复A展开，让后面的运行截图展示实际字段而非只有折叠标题。
  // 所有覆盖更新都留在A，混合类型选择不应把B自动切成同一集合。
  // 这里没有文件导入成功提示，不用“按钮被点到”替代字段结果断言。
  for (const [selection, labels] of [["0-2", ["缩放", "位置 X", "位置 Y", "旋转", "不透明度"]], ["0-3", ["淡入", "淡出"]], ["2-3", []], ["0-2-3", []]]) {
    await ctx.run(`document.querySelector('${scope("A")} [data-inspector-selection="${selection}"] button').click()`); await ctx.delay(80);
    const actual = await ctx.run(`[...document.querySelectorAll('${scope("A")} label')].map(e=>e.firstElementChild.textContent)`);
    ctx.smoke.check(`UI05: ${selection} selects only common fields`, JSON.stringify(actual) === JSON.stringify(labels));
  }
  await choose(ctx, "scene_01.mp4");
  await ctx.run(`document.querySelector('${scope("A")} button[aria-label="重置"]').click()`); await ctx.delay(80);
  // 这一行前置reset不可删除：若确认值仍是80，再reset到100会发生value变化。
  // value变化本来就会刷新草稿，那样无法检验“确认值未变”的真实漏洞。
  // 先把确认值置100，再输入invalid，第二次重置仍为100才有反证价值。
  // 错误状态在Enter后产生，不是测试手工添加aria-invalid或红边。
  // invalid选用明显非数字字符串，避免不同浏览器对科学计数法的合法解析差异。
  // 公开input是text型数字草稿，故浏览器不会先把invalid自动清成空串。
  // reset之后要求文本100.00，既证明丢弃错误，也证明精度初始化仍正确。
  // 仅仅去掉error属性但留下invalid文本不会通过此断言。
  // 第一个重置针对变换组，当前该组包含缩放、位置、旋转和不透明度。
  // 错误输入只在缩放，不需要为每个字段复制一份同构reset测试。
  // 共用字段保证同样生命周期规则也用于位置与旋转，差异由范围参数表达。
  // 类型组合返回空字段后再选视频，分组应重新按有效字段生成，而非复用音频组。
  // 折叠后仍可从标题展开，测试最后这一步不是重建整个样板页面。
  // 若A收起导致B也收起，可能是共享open布尔值，断言会明确指出隔离错误。
  // 如果只是把内容透明而标题仍报expanded，后续公共控件可见范围断言会发现。
  await edit(ctx, "缩放", "invalid");
  await ctx.run(`document.querySelector('${scope("A")} button[aria-label="重置"]').click()`); await ctx.delay(80);
  ctx.smoke.check("UI05: reset clears an invalid draft even when its confirmed default is unchanged", await value(ctx, "A", "缩放") === "100.00" && await ctx.run(`!document.querySelector('${scope("A")} input[aria-invalid]')`));
  await ctx.run(`document.querySelector('${scope("A")} [data-editor-group] button[aria-expanded]').click()`); await ctx.delay(80);
  ctx.smoke.check("UI05: collapsing A leaves B expanded and its fields reachable", await ctx.run(`document.querySelector('${scope("A")} [data-editor-group] button').getAttribute('aria-expanded')==='false'&&document.querySelector('${scope("B")} [data-editor-group] button').getAttribute('aria-expanded')==='true'`));
  await ctx.run(`document.querySelector('${scope("A")} [data-editor-group] button[aria-expanded]').click()`);
}

// 先输入非法数，再Escape，确认错误草稿没有污染已经确认的100。
// 合法小数用实际焦点转移提交，覆盖Enter之外的公共blur路径。
// 重置用真实按钮，不能直接调用样板setState把值改回默认。
// B与A同页，折叠A变换组之后B仍展开，验证分组生命周期独立。
async function checkDrafts(ctx) {
  // 缩放下限大于零，-2是明确非法值，不依赖浏览器本身的number类型夹限。
  // 文本输入仍保留-2，产品在Enter时报告错误而非打字时强行改成最小值。
  // B的错误属性不存在，检查的是错误状态隔离而不仅仅是B数字相同。
  // Escape恢复已确认100.00，不能把错误草稿变成最近一次确认值。
  // X坐标12.34合法，提交后精度保留两位，不取整为12。
  // 使用切焦到B按钮触发A失焦，覆盖Enter以外的实际blur通路。
  // A确认12.34时B仍为960，坐标源没有被误保存在共享项目对象中。
  // 分组重置根据项目中心恢复960，不应误取首素材宽度的一半。
  // reset按钮定位当前A的第一个组，该时刻A明确处于视频变换表单。
  // 如果前置选择不对，读值会是undefined，不能被Number转换成零误过。
  // 每条断言在操作之后读取UI，测试没有向确认值属性写入预期结果。
  // 草稿确认与失焦分步执行，可以发现回调值没有回流到受控输入的问题。
  await edit(ctx, "缩放", "-2");
  ctx.smoke.check("UI05: invalid draft stays local and does not mark B invalid", await ctx.run(`!!document.querySelector('${scope("A")} input[aria-invalid=true]')&&!document.querySelector('${scope("B")} input[aria-invalid]')`));
  await ctx.run("document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");
  await ctx.delay(60);
  ctx.smoke.check("UI05: Escape restores the confirmed scale", await value(ctx, "A", "缩放") === "100.00");
  await edit(ctx, "位置 X", "12.34", "Tab");
  // 合成Tab只把该键交给输入处理，不自动模拟操作系统的焦点导航。
  // 下方.focus才造成真实文档内的blur，因此报告不能写“人工Tab已验证”。
  // 这一区分也防止以后把代码改成dispatchEvent('blur')而没有真实焦点前提。
  // A的确认值需在失焦后再读取，失焦前看到12.34仍可能仅仅是草稿。
  // B项目中心960从同一项目参数得到，但样板values不同份。
  // B如果也变成12.34，说明不是字段格式化问题，而是共享状态归属错误。
  // 鼠标点击reset通常也会触发blur，单独的blur路径提前验证可帮助定位失败阶段。
  await ctx.run(`document.querySelector('${scope("B")} button').focus()`); await ctx.delay(60);
  ctx.smoke.check("UI05: blur commits decimal project coordinates in A only", await value(ctx, "A", "位置 X") === "12.34" && await value(ctx, "B", "位置 X") === "960.00");
  await ctx.run(`document.querySelector('${scope("A")} button[aria-label="重置"]').click()`); await ctx.delay(60);
  // 默认中心通过确认结果读取，不从propertyDefaults导入答案，避免同错一起通过。
  // 960来自已知1920宽的工程，不允许用素材640宽的一半320替代。
  // 同时保留Y与其他字段的显示，组重置应是参数集合操作而不是清空检查器。
  // 这条重置先测确认值变化，另一组专门测确认值不变但草稿错误的边界。
  // 两种条件不同，不能用一次“reset按钮能点”替代两个数据路径。
  // 测试不要求真实视频画面移动，因为样板没有接入画布变换。
  // 这避免把纯UI确认成功错误包装成实际效果验收。
  ctx.smoke.check("UI05: group reset uses current project center", await value(ctx, "A", "位置 X") === "960.00", String(await value(ctx, "A", "位置 X")));
}

// 专项入口仍由原冒烟检查构建指纹、协议、preload和错误收集。
// 截图来自capturePage，不重画组件，也不把静态样板当真实效果截图。
// 仅导航到公开samples入口，不新增测试专用产品状态写接口。
async function checkVideoUiInspector(ctx) {
  // 进入公开样板路由，不给正式工作区塞模拟值或替换媒体IPC响应。
  // 首个输入出现才开始编辑，页面未水合时不能把点击丢失算作产品行为。
  // 运行结束保留实际截图，能同时看到A与B的参数和能力说明。
  // screenshot目录来自外层临时工作区，不覆盖设计参考图。
  // 新图片不是“缩放已经作用于视频”的证据，仅证明同一个检查器真实运行。
  // 最后选择视频用于清楚展示字段，前面的异常和混合断言仍保留在运行日志。
  // 不重置外层错误集合，早先状态回归失败会继续导致整套非零退出。
  // 与原控件、素材和预览回归顺序执行，不开第二个Electron争抢单实例锁。
  await ctx.win.loadURL("app://app/tools/video/editor/samples");
  await ctx.wait("document.querySelector('[data-inspector-sample=A] input')");
  // 隐藏窗口需焦点模拟才会产生真实focusout；否则读到的可能只是未确认草稿。
  await ctx.win.webContents.debugger.sendCommand("Emulation.setFocusEmulationEnabled", { enabled: true });
  await checkDrafts(ctx); await checkMixed(ctx); await checkTypes(ctx); await checkCombinations(ctx);
  await choose(ctx, "scene_01.mp4");
  await ctx.run("document.querySelector('[data-inspector-sample=A]').scrollIntoView()");
  // scrollIntoView仅用于截图取景，不在行为断言前修改容器尺寸或裁掉错误提示。
  // 截图时A明确单选视频，B保留独立默认视频，可直接比较两个检查器来源说明。
  // 截图不叠加测试通过水印，避免遮住长名称、省略和滚动边界。
  // 运行证据保存到外层root，文档链接只复制最终一次静态构建对应文件。
  // 旧失败日志仍保留，最终通过并不删除曾经发现的样板兼容问题。
  // 关闭此页后A/B覆盖状态释放，正式页不会恢复练习输入。
  // 这里没有本地存储断言，因为样板根本不具备持久化能力。
  fs.writeFileSync(path.join(ctx.root, "ui-05-inspector.png"), (await ctx.win.webContents.capturePage()).toPNG());
}
module.exports = { checkVideoUiInspector };

scripts/lib/check-video-ui-integration.j:
/** UI-08正式入口集成反证；复用LIVE窗口和真实文件，不复制启动、导入或播放器。 */
const fs = require("node:fs"), path = require("node:path");
// 本helper只借用外层公开DOM驱动，没有访问React私有状态或替换工程数组。
// 视频先由外层生产ffprobe读取，搜索结果里的文件名来自真实磁盘文件。
// 系统选择框另由LIVE-01验证；本组选择结果仍是路径夹具，不能冒称人工多选。
// 事件使用DOM公开入口，菜单、焦点、搜索和锁最终都交给产品自己的处理器。
// 像检查同一张订单的货架、收据和配送记录，必须同时核对多个区域才发现串单。
// 截图保留当前正式实例，不切去静态样板或用DEMO文件充当已导入视频。
// 主进程有界等待由原套件提供，helper不会新增无限轮询或计时器假进度。
// 每项断言汇入原harness，新增检查失败不能被最后正常退出掩盖。
// 用户前台应用保持不动；离屏图和自动事件不替代资源管理器人工拖入。

// 空工程必须在导入前检查，才能发现残留演示文件名或初始固定片段。
// frame要有面积、纯黑背景且没有可见占位子节点，不能靠隐藏文字颜色蒙混过去。
// 项目时钟仍显示零，黑画布并不意味着从DOM删除整个节目区。
// 保存、导出和效果编辑继续禁用，空工程也不能出现可点击的假动作。
// 图像文件是实际Electron像素，非设计稿；临时目录由外层统一归档。
// 这里不对屏幕色彩或系统缩放作结论，计算颜色只证明浏览器样式的来源。
// 没有媒体时也不挂空src播放器，避免无意义的解码请求或旧音频残留。
// 只检查正式host中的内容，不把独立样板路由里的演示数据当作污染。
// children检查针对frame，不检查整个R03：标题和走带区本来就应该继续存在。
// 仅断言innerText为空会漏掉无文字图标，所以这里要求画布没有任何子元素。
// 只检查背景黑色也不够，旧封面可能仍盖在黑色背景上，二者必须一起满足。
// 面积大于零防止display:none或塌陷后“看不见提示”被错误算作修复。
// 无片段是正式空工程的事实，不能预放一段黑色演示片段来实现黑屏。
// 无媒体元素保护零源生命周期，不把暂停中的隐藏播放器当成空画布。
// 本组未检查真实节目空隙的连续播放，当前播放器没有自动接播能力。
// 真实素材解码失败由LIVE-01另行保留错误，安静空画布不能覆盖该分支。
async function checkIntegrationEmpty(ctx) {
  ctx.smoke.check("UI08: empty formal canvas is black without placeholder or media", await ctx.run("(()=>{const f=document.querySelector('[data-editor-preview-frame]');return f.children.length===0&&getComputedStyle(f).backgroundColor==='rgb(0, 0, 0)'&&f.getBoundingClientRect().width>0&&!document.querySelector('[data-live-video-session] video,[data-live-video-session] audio')&&!document.querySelector('[data-editor-clip]')})()"));
  fs.writeFileSync(path.join(ctx.root, "ui-08-empty-black.png"), (await ctx.win.webContents.capturePage()).toPNG());
}

// 搜索先造一个不存在的名字，再搜真实竖屏文件，排除“任意输入都显示全部”的假接线。
// 输入用原生value setter和input事件通知React，不直接改结果DOM来制造成功。
// 搜索前两份视频均已成功导入，随后仅改变本面板query，不能改变工程数组。
// 搜索失配有恢复入口，清除后原两份素材ID应继续存在，不重新探测或生成新身份。
// 音频类型目前没有独立导入，所以筛到零结果是正常UI状态，不是素材丢失。
// 恢复全部后点击竖屏素材，只应打开源预览，不能隐式建时间线片段。
// 源播放器真实加载是否成功仍由原套件验证，这里主要核对选择归属与类型筛选。
// 属性面板不能跟素材高亮走，空工程选择素材后仍没有片段属性目标。
// 素材选中ID从真实按钮读取，不按文件名推导一个假UUID。
// 返回节目必须卸载源，最终黑画布不能残留上一段的封面或播放器。
// helper结束恢复全部筛选和节目模式，原LIVE后续入轨沿用同一素材会话。
// 若搜索错误地清空assets，原两行恢复检查会失败，而不是依赖后续重新导入修好。
// “视频”与“音频”按钮标签使用当前中文测试环境，产品本身仍按i18n取文案。
// 测试不通过改主题或重载页面恢复状态，状态切换必须在同一实例内完成。
// 只把自动事件记为自动验证，未宣称实际按键顺序或输入法已人工验收。
async function checkIntegrationMedia(ctx) {
  const query = async value => { await ctx.run(`(()=>{const e=document.querySelector('[data-editor-region=R02] input[type=search]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,${JSON.stringify(value)});e.dispatchEvent(new Event('input',{bubbles:true}))})()`); await ctx.delay(80); };
  // 输入前setter来自原生prototype，避免绕过React受控字段的变化检测。
  // 只发input不发键盘快捷键，本组不能证明输入法或人工Tab路径。
  // 80ms只给状态提交一个有限间隔，不伪造探测进度或替代媒体ready事件。
  // 未匹配断言同时检查片段数，防止搜索被误接到时间线删除命令。
  // 未匹配文案从真实列表读取，不由测试额外插入一条status节点。
  // 精确关键词只命中第二份真实文件，能识别第一份结果缓存没有更新的问题。
  // 清空query后再切音频，确保类型条件本身有作用，不被残留搜索词替代。
  // 类型按钮的pressed状态由产品kind控制，测试不手动改aria-pressed。
  // 恢复全部用公开按钮，没有调用组件setKind或重载整个会话。
  // 两份原视频都仍应存在，重复身份和临时新ID也会让后续片段引用检查失败。
  // 素材点击发生在空时间线，故任何新片段都属于意外业务副作用。
  // 源查看只拥有素材时钟，属性空选择的断言能发现两个选择被绑成一个。
  // 返回后通过empty状态等待React切换，不仅等待按钮点击函数返回。
  // 播放资源释放检查真实video/audio节点，不把按钮文案变了当作清理完成。
  // 返回后素材高亮允许保留，这与退出源查看是两个不同用户意图。
  await query("does-not-exist-ui08");
  ctx.smoke.check("UI08: unmatched search shows zero rows without creating clips", await ctx.run("!document.querySelector('[data-editor-asset]')&&!document.querySelector('[data-editor-clip]')&&document.querySelector('[data-editor-media-results]').textContent.includes('没有符合搜索')"));
  await query("portrait-silent");
  ctx.smoke.check("UI08: exact search returns only the real portrait filename", await ctx.run("document.querySelectorAll('[data-editor-asset]').length===1&&document.querySelector('[data-editor-asset]').title==='portrait-silent.mp4'"));
  await query("");
  await ctx.run("document.querySelector('[data-editor-region=R02] button[aria-label=音频]').click()");
  ctx.smoke.check("UI08: audio filter does not relabel imported videos", await ctx.run("!document.querySelector('[data-editor-asset]')&&!document.querySelector('[data-editor-clip]')"));
  // React筛选更新不是同步DOM替换，先等两行恢复才点第二行，避免驱动抢在提交前。
  await ctx.run("document.querySelector('[data-editor-region=R02] button[aria-label=全部]').click()");
  await ctx.wait("document.querySelectorAll('[data-editor-asset]').length===2");
  await ctx.run("document.querySelectorAll('[data-editor-asset]')[1].click()");
  await ctx.wait("document.querySelector('[data-editor-preview-mode=source]')");
  ctx.smoke.check("UI08: asset viewing keeps the inspector and timeline unselected", await ctx.run("document.querySelectorAll('[data-editor-asset]').length===2&&!document.querySelector('[data-editor-clip]')&&!document.querySelector('[data-editor-inspector-clip]')&&document.querySelector('[data-editor-asset][aria-current=true]').title==='portrait-silent.mp4'"));
  await ctx.run("document.querySelector('[data-editor-region=R03] button[aria-label=返回节目预览]').click()");
  await ctx.wait("document.querySelector('[data-editor-preview-state=empty]')");
  ctx.smoke.check("UI08: return to empty program releases source and restores plain black", await ctx.run("!document.querySelector('video,audio')&&document.querySelector('[data-editor-preview-frame]').children.length===0"));
}

// 两个真实V1实例已入轨，本组锁空闲A1/A2，使失败只能来自锁而不是轨道占用。
// 保留完整片段快照，拒绝时数量相同仍不够，还要保护起止、身份及选中值。
// 先点目标片段再保存快照，避免菜单打开时合法选中切换被误判为修改工程。
// 分离仍点击真实公共菜单，能发现纯函数已修但正式会话忘传锁表的断层。
// 两条目标锁住不应消除源预览或素材高亮，错误消息只留在时间线状态栏。
// 解锁后原正常分离套件会再次执行成功路径，因此不能用永久禁用分离来过关。
// 源轨随后锁定，向disabled片段投递Delete、方向键和右键事件属于负向绕过测试。
// 合成事件故意绕过正常鼠标命中限制，产品处理器仍必须守住同一个源锁门槛。
// 没有用隐藏菜单或禁用测试事件掩盖问题，检查的是最终工程快照和菜单是否生成。
// 鼠标创建/拖动锁门槛由原时间轴回归同时覆盖，本组重点补菜单与键盘入口。
// 属性实际效果仍禁用，锁检查不是宣称变换或音量参数已经接入工程。
// 整体只改变锁表和查看目标，没有产生音频文件或对磁盘视频进行任何编辑。
// 结束恢复所有锁，后续LIVE横滚、复制和分离继续在同一工程运行。
// 这组测试是自动行为反证，不代表人在真实窗口按过完整快捷键路径。
// 正式检查器现在开放五个构图字段，所以不能继续要求所有input都禁用。
// 仍禁用的是速度与两个淡入淡出，精确数量反证未接通效果被误开放。
// 只看导出禁用不足以判断字段能力，因此两类断言分别保留。
// 构图真实值与画面同步由专门helper覆盖，本组关心正式装配能力边界。
// 未接通效果不能通过传一个空回调把按钮变成可点击。
// 轨道锁另需让五个构图字段也禁用，不能与“未接通所以禁用”混为一谈。
// 目标轨锁反例仍用空闲目标轨，排除碰撞碰巧导致拒绝的假通过。
// 这一调整是新增真实能力后的期望更新，没有放松保存和导出的原限制。
// 样板仍可演示速度草稿，这不改变正式工作区能力清单。
// 自动集成通过不修改UI08既有人工待验项目的状态。
async function checkIntegrationLocks(ctx) {
  const id = (await ctx.clips())[0].id;
  await ctx.click(`[data-editor-clip="${id}"]`);
  // before包含当前selected标记，后续失败不能顺便清掉检查器目标。
  // 两条音轨最初均为空，因此无音频安排不是占用导致分离失败的巧合。
  // 锁按钮用各自轨道头限定，不能误点V1的同名锁而提前阻断源操作。
  // 菜单目标用独立clipId，多个同源片段不会因文件名相同而被混为一条。
  // 分离菜单关闭不等于成功，状态栏必须明确轨道已锁定。
  // 不检查“已完成”通用文案，因为那会把一个失败动作错误记录成成功。
  // 拒绝后A1和A2都没有新增片段，不能只比较V1数量来判断原子性。
  // 锁状态测试后逐一解锁，不用清空工程来恢复前置，避免掩盖数据损坏。
  // 锁V1时发送ArrowRight也不能移动一帧，尤其不能由键盘绕过disabled按钮。
  // Delete合成事件即使送达React冒泡链，提交边界仍应拒绝。
  // 右键合成事件不要求实际鼠标能点中disabled元素，目的正是反证越过UI保护。
  // 菜单没有生成是辅助证据，完整片段快照不变才是业务保护的最终证据。
  // 解锁恢复后再截图，两段仍是原来的时间与身份，便于人工对照。
  // 后续正常分离会验证原视频的audioDetached标记与真实音频播放，不在此读取私有状态。
  // 元数据hasAudio来自真实探测，不能用.mp4后缀判断一定可以分离声音。
  // 本组未提取wav，磁盘源完整保留，因此不存在假音频导入成功的提示。
  // 未测试多轨同步播放，A1/A2在这里仅是可独立安排的音频通道。
  // 如最终截图中预览还在加载，原媒体事件断言仍会单独决定是否可播放。
  const before = JSON.stringify(await ctx.clips());
  await ctx.click('[data-editor-track-head=A1] button[aria-label=锁定]');
  await ctx.click('[data-editor-track-head=A2] button[aria-label=锁定]');
  await ctx.openLiveMenu(id);
  await ctx.click('[data-live-clip-menu] button[aria-label=分离音频到音频轨]');
  ctx.smoke.check("UI08: formal detach into two locked targets refuses without a partial edit", JSON.stringify(await ctx.clips()) === before && await ctx.run("document.querySelector('[data-timeline-notice]').textContent.includes('轨道已锁定')&&!document.querySelector('[data-editor-track-lane=A1] [data-editor-clip],[data-editor-track-lane=A2] [data-editor-clip]')"));
  await ctx.click('[data-editor-track-head=A1] button[aria-label=锁定]');
  await ctx.click('[data-editor-track-head=A2] button[aria-label=锁定]');
  await ctx.click('[data-editor-track-head=V1] button[aria-label=锁定]');
  await ctx.run(`(()=>{const e=document.querySelector('[data-editor-clip="${id}"]');for(const key of ['Delete','ArrowRight'])e.dispatchEvent(new KeyboardEvent('keydown',{key,bubbles:true,cancelable:true}));e.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:500,clientY:500}))})()`);
  ctx.smoke.check("UI08: locked source rejects keyboard and context-menu bypass", JSON.stringify(await ctx.clips()) === before && await ctx.run("!document.querySelector('[data-live-clip-menu]')&&[...document.querySelectorAll('[data-editor-track-lane=V1] [data-editor-clip]')].every(e=>e.disabled&&!e.draggable)"));
  await ctx.click('[data-editor-track-head=V1] button[aria-label=锁定]');
  // 正式工作区只应该出现真实导入文件名，样板名称不能随默认参数漏进来。
  // 当前仍只有视频安排，未分离前不应出现任何波形示意路径。
  // 禁用能力从实际button.disabled核对，视觉变灰不算真正阻止操作。
  // 未传入效果提交回调时属性数值保持只读，不能把样板草稿伪装成实际变换。
  // 这里只扫描正式host，独立samples继续允许演示波形、固定项目与草稿编辑。
  // 未检查的未来动作不因此算通过，能力清单仍逐项标注已实现、仅UI或未接通。
  // 用户文件名可能任意，当前已知真实测试文件不含这些样板标识，反证没有歧义。
  // 按钮断言限定项目栏与属性栏，避免把源播放器真实播放按钮误当未接通功能。
  ctx.smoke.check("UI08: formal project excludes demo names and keeps unavailable effects/export disabled", await ctx.run("(()=>{const h=document.querySelector('[data-live-video-session]');return !/scene_0[12]|bg_01|voice_01|春日短片/.test(h.textContent)&&h.querySelector('[data-editor-region=R01] button[aria-label=导出]').disabled&&[...h.querySelectorAll('[data-editor-region=R04] input')].filter(e=>e.disabled).length===3})()"));
  fs.writeFileSync(path.join(ctx.root, "ui-08-integrated-real-project.png"), (await ctx.win.webContents.capturePage()).toPNG());
}

// 媒体节点清理观测不等于底层解码器内存已量化释放，未测显存占用不作结论。
// 横竖视频与不同帧率来自两份真实编码文件，不能外推所有容器和编解码器。
// 系统缩放需要Windows实际环境，CDP容器尺寸矩阵只证明布局响应。
// 扬声器试听需人工确认，本helper既不打开系统音量也不把timeupdate当听到声音。
// 三个阶段由原串行流程调用，避免空工程、导入后和入轨后互相污染前置条件。
// 仅导出测试入口，不增加产品window或preload能力，也不制造另一套运行状态。
module.exports = { checkIntegrationEmpty, checkIntegrationMedia, checkIntegrationLocks };

scripts/lib/check-video-ui-media.js:
/**
 * UI-03 的真实素材面板回归，复用既有 Electron 窗口和静态导出。
 * 素材选择像给货架原件贴标签，不能挪动时间轴上的片段副本。
 * 测试同时核对列表变化和时间轴不变，避免仅看高亮就误判通过。
 * 默认五项与样板异常数据都由产品组件渲染，不修改 React 内部状态。
 * 场景按钮只切换固定夹具，不将其当作真实探测完成。
 * 所有输入走 DOM 输入事件或 Chromium 按键，不调用组件回调作捷径。
 * 等待和截图使用外层有上限的主进程节拍，不依赖后台 rAF。
 * 该 helper 不创建新进程，不读取真实素材，也不清理用户目录。
 */
const fs = require("node:fs"), path = require("node:path");
// 主工作区只有一个 R02；样板需要带 A/B 作用域，防止总是操作首个实例。
// 稳定素材 ID 用于定位，文件名仍可变长或按搜索条件改变。
// 选择器全部由测试常量组成，不把外部网络数据拼进表达式。
const MAIN = "[data-video-editor-ui] [data-editor-region=R02]";
// MAIN 不匹配独立样板页，路由跳转后误用它会失败而非命中别的素材行。
// sample 的边界是整个素材面板样例，不是 UI-02 的字段样例 A/B。
// 两种样板虽然都叫 A/B，data 属性不同，测试不能跨组混用选择器。
// 用 data 标记代替中文标题，语言切换不应该改变元素身份。
// 文件名只用于核对展示结果，不用作查询选择器的 CSS 拼接片段。
// “voice”身份与“voice_01.wav”名称分开，重命名不会改变行归属。
// 这也避免包含空格、方括号或中文的文件名破坏定位表达式。
// MAIN 的宿主限制保留旧版工具的独立性，不会选中 legacy 列表。
const sample = id => `[data-editor-media-sample=${id}]`;

// 输入 setter 配合 input 事件走 React 的受控字段通路。
// 文本 JSON 编码只用于 executeJavaScript，不作为 shell 命令拼接。
// 输入前主动聚焦，可以接着测试 Escape 清词与可见焦点。
// wait 后再读结果，避免同一任务里先读到旧受控值。
// 不直接修改筛选结果 DOM，否则无法验证实际过滤逻辑。
async function search(ctx, scope, value) {
  // 原生 setter 避开 React 对值的追踪缓存，随后仍必须派发 input。
  // 只写 e.value 而不发事件会改外观却不更新受控 query，不能用作有效测试。
  // 本 helper 不直接调整类型，查询变化应与先前按钮条件共同生效。
  // 参数 scope 指向面板，因此多个搜索框存在时不会误输入到 B。
  // value 完整保留空白，规范化应由产品过滤逻辑处理而非测试预处理。
  // 等待输入值后，调用方继续验证结果项，单看输入回显不足以证明搜索有效。
  // 大写用例不通过测试先转小写，避免把应验证的大小写规则搬进测试。
  // 本轮不模拟中文输入法组合事件，其支持范围在交付限制中明确保留。
  // 搜索结果由面板重新计算，测试不读取或缓存上一次 results 数组。
  // 如果组件没有受控更新，后面的结果数量断言会直接失败。
  await ctx.run(`(()=>{const e=document.querySelector('${scope} input[type=search]');e.focus();Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,${JSON.stringify(value)});e.dispatchEvent(new Event('input',{bubbles:true}))})()`);
  await ctx.wait(`document.querySelector('${scope} input[type=search]').value===${JSON.stringify(value)}`);
}
// 同一入口用于全部、视频、音频、图片，验证公共按钮的回调与 pressed。
// 固定顺序来自确认稿，测试不按翻译文字寻找按钮。
// 分类是纯 UI，不调用导入服务或切换节目预览。
// 短等待只用于让已触发的同步界面更新提交，不等待未知业务成功。
async function filter(ctx, scope, index) {
  // role=group 将分类按钮与顶部导入、状态恢复按钮区分开。
  // index=0 对应全部，不是当前可见结果的第一项。
  // 切换类型必须立即改变列表，而不能等一次真实导入才刷新。
  // 六十毫秒不是网络超时预算，只用于提交已经发生的本地状态更新。
  // 若结果仍错误，后续数量与身份断言会明确失败，不增加重试轮数。
  // 不在按钮点击后直接改 aria-pressed，状态必须由面板真实渲染。
  // 类型条件不应修改文件名，因此断言仍使用原来的稳定素材 ID。
  await ctx.run(`document.querySelectorAll('${scope} [role=group] button')[${index}].click()`);
  await ctx.delay(60);
}
// 原生 Enter 需要字符事件才能覆盖按钮默认激活，而非仅 React 键事件。
// Escape 没有字符输入，不能向搜索词插入控制字符。
// keyUp 必须配对，避免下一步误认为按键仍按住。
// 事件只发送给隔离窗口，不影响用户当前应用。
// 每一步最终由实际 DOM 断言判读，按键发送成功本身不算通过。
async function key(ctx, name) {
  // 焦点由调用方提前放到目标控件，不用合成 click 来代替按键。
  // Enter 用于验证图片行能从键盘选择，与鼠标 click 路径互补。
  // Escape 用于验证搜索清词，不应该把类型一并恢复为 all。
  // 本轮没有新增全局播放快捷键，搜索中的按键不负责时间线走带。
  // 隐藏窗口的焦点语义由原套件调试设置维持，不修改产品事件处理器。
  // 发送完成后读 ARIA 和值，不能以调试协议没有抛错作为通过依据。
  ctx.win.webContents.sendInputEvent({ type: "keyDown", keyCode: name });
  if (name === "Enter") ctx.win.webContents.sendInputEvent({ type: "char", keyCode: "\r" });
  ctx.win.webContents.sendInputEvent({ type: "keyUp", keyCode: name });
  await ctx.delay(60);
}
// capturePage 保存当前运行像素，不复制设计图冒充运行证据。
// 截图前留给合成器一个有限间隔，主题过渡另外由条件等待负责。
// 文件名由内部测试提供，输出归隔离临时目录所有。
// 本函数不裁切或修图，窗口外壳与滚动边界会完整保留。
// 所有断言仍独立于图片写入成功与否。
async function shot(ctx, name) {
  // root 由外层临时目录生成，本函数不会猜测 Downloads 或用户桌面。
  // 每个状态使用不同文件名，浅色和深色证据不会互相覆盖。
  // capturePage 包含当前滚动位置，因此调用方要明确定位欲检查的样板。
  // 截图尺寸来自真实调试视口，不把小图放大后声称测了宽屏。
  // 软件渲染的图像能够验证布局，但不能代表硬件解码或 GPU 性能。
  // 捕获失败向外层传播，不能丢掉截图还给出一份“已验证”报告。
  await ctx.delay(200);
  fs.writeFileSync(path.join(ctx.root, `${name}.png`), (await ctx.win.webContents.capturePage()).toPNG());
}

// 从返回后的默认工程开始，先测可见双栏宽度，再恢复大布局。
// 三种类型由同一个素材列表渲染，图片次行不能显示虚构源时长。
// 选择基准之外的图片，能发现错误绑定右侧属性或时间轴状态的问题。
// 保存内容快照而非仅比较节点引用，防止节点不换却偷偷改了属性。
// 搜索输入含大写和两端空白，预期命中 voice_01.wav 一项。
// 加入类型条件后取交集，不能忽略音频分类而显示同名视频。
// 查询无结果不能回退到全部，否则用户会以为搜索条件已生效。
// 清除按钮恢复全部五项，并保留图片的选中 ID。
// Escape 只清词；当前音频分类必须仍为 pressed。
// 键盘原生 Enter 选择图片，不让自动化仅覆盖鼠标点击路径。
// 焦点轮廓从计算样式读取，证明 CSS Module 在运行页面实际生效。
// 导入按钮仍 disabled，原因必须关联实际存在的说明节点。
// 选择动作前后没有新时间轴片段，固定 clip-02 仍为选中。
// 节目画面 src 和属性文本也必须完全一致，不能只核对片段数量。
// 搜索/分类/选择都局限本面板，测试不接受隐藏的播放元素。
// 图片无源时长的反证读取次行文本，不靠文件后缀推断。
// 默认行数严格为五项，异常夹具不应混进正式演示工程。
// 选择筛选外素材后隐藏它，取消条件时不能改成首项高亮。
// 同时检查清词后的搜索输入为空，避免只切回类型而留下不可见条件。
// 错误消息属于下一组显式样板，不在默认工作区人为注入异常。
// 本组不声明真实素材预览已完成，节目仍为静态 scene-02。
// 输入事件不触发保存，因此不会写游客文档中的项目内容。
// 所有比较基于用户可见身份和 ARIA，不访问 React fiber 或内部 hook。
// 测试恢复完整五项后截图，便于与已确认原图对照。
async function mainFlow(ctx) {
  // 1280 是实际编辑器主区宽度，浏览器还包含导航和宿主边界。
  // sizeHost 自行量取 inset，不能把总窗口宽度误当作 R02 可用宽度。
  // baseline 中包含片段 ID 与 pressed 两部分，能发现新增片段与串选两类问题。
  // 属性文本包含数值，不只比较“片段属性”标题有没有变化。
  // 节目 src 比较的是解码用地址，不能只读 alt 中未变的文件名。
  // 图片项的时长反证在中文环境执行，次行不应包含秒单位 s。
  // 搜索无结果时会检查行数为零，避免只增加提示却仍保留不匹配内容。
  // 恢复五项时也检查 background 高亮，防止清除条件顺带清空选择。
  // 导入提示使用 aria-describedby 查实际节点，不能只确认有 title 装饰。
  // 默认五项里既有配音又有音乐，清词后应恰好返回两条音频。
  await ctx.sizeHost(1280, 800);
  ctx.smoke.check("Media search is enabled while real import has its own disabled reason", await ctx.run(`(()=>{const p=document.querySelector('${MAIN}'),b=p.querySelector('[data-editor-action]');return !p.querySelector('input').disabled&&b.disabled&&document.getElementById(b.getAttribute('aria-describedby')).textContent.includes('导入与探测')})()`));
  await ctx.run("window.__mediaBaseline={inspector:document.querySelector('[data-editor-region=R04]').textContent,preview:document.querySelector('[data-editor-region=R03] img').src,clips:[...document.querySelectorAll('[data-editor-clip]')].map(e=>[e.dataset.editorClip,e.getAttribute('aria-pressed')])}");
  await filter(ctx, MAIN, 3);
  await ctx.run(`document.querySelector('${MAIN} [data-editor-asset=background]').focus()`); await key(ctx, "Enter");
  ctx.smoke.check("Keyboard selects image with visible focus and no invented source duration", await ctx.run(`(()=>{const e=document.querySelector('${MAIN} [data-editor-asset=background]');return e.getAttribute('aria-current')==='true'&&parseFloat(getComputedStyle(e).outlineWidth)>=2&&!e.querySelector('small').textContent.includes('s')})()`));
  await filter(ctx, MAIN, 2); await search(ctx, MAIN, "  VOICE  ");
  ctx.smoke.check("Case-insensitive filename search intersects audio type", await ctx.run(`document.querySelectorAll('${MAIN} [data-editor-asset]').length===1&&!!document.querySelector('${MAIN} [data-editor-asset=voice]')`));
  await key(ctx, "Escape");
  ctx.smoke.check("Escape clears only search and retains the audio filter", await ctx.run(`document.querySelector('${MAIN} input').value===''&&document.querySelectorAll('${MAIN} [data-editor-asset]').length===2&&document.querySelectorAll('${MAIN} [role=group] button')[2].getAttribute('aria-pressed')==='true'`));
  await search(ctx, MAIN, "not-present");
  ctx.smoke.check("No matches differs from an empty library and offers reset", await ctx.run(`document.querySelector('${MAIN} [data-editor-media-results]').textContent.includes('没有符合')&&document.querySelectorAll('${MAIN} [data-editor-asset]').length===0`));
  await ctx.run(`document.querySelector('${MAIN} [data-editor-media-results] [data-editor-action]').click()`); await ctx.delay(60);
  ctx.smoke.check("Reset restores five items and previously hidden selection", await ctx.run(`document.querySelectorAll('${MAIN} [data-editor-asset]').length===5&&document.querySelector('${MAIN} input').value===''&&document.querySelector('${MAIN} [data-editor-asset=background]').getAttribute('aria-current')==='true'`));
  ctx.smoke.check("Asset selection never changes inspector, program or clip state", await ctx.run("window.__mediaBaseline.inspector===document.querySelector('[data-editor-region=R04]').textContent&&window.__mediaBaseline.preview===document.querySelector('[data-editor-region=R03] img').src&&JSON.stringify(window.__mediaBaseline.clips)===JSON.stringify([...document.querySelectorAll('[data-editor-clip]')].map(e=>[e.dataset.editorClip,e.getAttribute('aria-pressed')]))"));
  await ctx.sizeHost(1600, 1000); await shot(ctx, "ui-03-media-light");
}

// 场景切换使用页面真实按钮，不设置 DOM 属性伪造 disabled 或状态。
// A/B 的外层控制区与内层面板按钮分别定位，避免点错导入入口。
// 每次切换只重置当前样板；B 的查询和选中在另一组另外断言。
// 场景集合由产品显式给出，不通过后端响应延迟制造不稳定超时。
async function scenario(ctx, index) {
  // :first-of-type 限定的是样例外部场景操作区，内部类型按钮不在其中。
  // 选择错误场景时后续占位断言会失败，不根据按钮文本自动修正索引。
  // 本 helper 固定操作 A，便于用 B 作为始终未变的反例。
  // 每次切换使用产品自己的 key 重建规则，测试不手动卸载组件。
  // 错误页保留原五项输入但不显示行，可暴露错误状态还允许旧数据交互的问题。
  // 场景之间没有真实请求，不能用此结果宣称已经覆盖网络取消竞态。
  await ctx.run(`document.querySelectorAll('${sample("A")} > div:first-of-type [data-editor-action]')[${index}].click()`);
  await ctx.delay(60);
}
// 整库 loading 应显示等待占位与 aria-busy，不允许继续搜索旧数据。
// error 应呈现独立错误说明，不允许把失败来源显示成空库。
// loading/error 都不给出假重试，也不会自动推进到成功状态。
// 空库则保留可用搜索，且没有“清除条件”伪恢复按钮。
// 无搜索结果在主区已验证，此处用真正的空数组作反例。
// 连续场景切换还核对 B 保持五项，防止共享状态污染其他实例。
// 不仅检查占位 data 标记，还读取输入 disabled 和实际文本。
// error 的 alert 来自既有 EditorPlaceholder，不新增一套反馈组件。
// loading 的 busy 属于整个面板，单行探测另在长列表测试。
// 原 five-items 起点用于下一组，确保错误状态离开后不残留禁用属性。
// 所有夹具为纯 UI，真实业务调用计数由外层再次断言为零。
// 场景按钮自身始终可用，否则用户无法在独立预览页查看其他状态。
// 状态变化不需要重新进入路由，也不写任何工程素材数据。
// 只在 A 操作，B 的未变是跨实例共用组件的实际证据。
async function libraryStates(ctx) {
  // loading 夹具不是空数组，因此零行必须由整库状态优先级产生。
  // error 同样携带旧素材，确保失败不会意外回退成可选旧列表。
  // B 的五项检查防止场景变量被错误提升到两个实例的共同父层。
  // empty 场景单独传空数组，和带条件的零结果有不同的数据前提。
  // 空库不展示清除按钮，因为清除条件无法凭空恢复不存在的素材。
  // 从空库恢复 ready 后继续运行搜索，能发现 input.disabled 残留。
  // 错误截图发生在 error 场景，文件名不会把 loading 状态误标成错误。
  // 错误文字与等待文字分别来自面板参数，行级缺图不应触发整库反馈。
  for (const [index, state] of [[1, "loading"], [3, "error"]]) {
    await scenario(ctx, index);
    ctx.smoke.check(`Media library ${state} blocks stale rows and search`, await ctx.run(`!!document.querySelector('${sample("A")} [data-editor-media-results] [data-editor-placeholder=${state}]')&&document.querySelector('${sample("A")} input').disabled&&document.querySelectorAll('${sample("A")} [data-editor-asset]').length===0&&document.querySelectorAll('${sample("B")} [data-editor-asset]').length===5`));
  }
  await shot(ctx, "ui-03-media-error"); await scenario(ctx, 2);
  ctx.smoke.check("Empty media library is searchable and has no false recovery action", await ctx.run(`document.querySelector('${sample("A")} [data-editor-media-results]').textContent==='没有素材'&&!document.querySelector('${sample("A")} input').disabled&&!document.querySelector('${sample("A")} [data-editor-media-results] button')`));
  await scenario(ctx, 0);
}

// 两个实例起初内容相同，先只筛 A，再检查 B 的原始五项仍存在。
// B 选择 voice 后，A 的默认 scene-02 不应被替换。
// 主区已验证筛选隐藏后恢复选择，此处补充不同实例与异常素材。
// 长列表同时包含可选缺图、不可选探测中与不可选错误行。
// 加载与错误都传入真实回调，仍由 MediaItem 的原生 disabled 阻止操作。
// 缺图行则有回调且可选，不能把所有异常统一禁用。
// 长文件名必须省略并保留全名提示，不增加横向整页滚动。
// 实际设置列表 scrollTop，标题位置保持不变，证明滚动归属正确。
// 列表包含多份同类音频，稳定 ID 不能因重复类型而合并。
// 截图先恢复顶部，保留长名、探测、错误和缺图在同一实例中的证据。
// 样板页滚动只用于把两个面板带入视口，不改变面板内部选择。
// B 在 A 场景切换时仍保留音频选中，这项检查覆盖数据替换的隔离边界。
// 不比较样板内的假成功消息，因为产品根本不提供这种消息。
// 单行探测不会把整个面板输入禁用，整库等待则在前组另验。
// 不检查文件是否真实存在，这些名称只对应独立静态演示内容。
// 本组不声称已覆盖千级素材库性能或真实音频波形生成。
// 列表外壳复用与主区相同，窄列长名仍走同一个 minmax/ellipsis 规则。
// title 核对全名，避免 CSS 截断时同时丢失辅助查看途径。
// 滚动前后只比较标题 top，不能仅凭 overflow:auto 源码宣布通过。
// 行固定高度保证缺图占位不把后续内容推到工具栏上面。
// 选中标记仍按稳定 ID，过滤后的位置不参与选择计算。
// 音频显示相同波形不意味着同一素材对象，ID 区分每份演示资源。
// UI-02 样板的片段选择保持独立，外层已有对应回归继续运行。
// 这里没有拖动素材入时间轴的实现，不派发拖放事件伪造剪辑能力。
// 错误和加载行的 disabled 由 MediaItem 计算，测试不注入 disabled 属性。
// 主区的五项仍是默认数据，样板长列表不能改变默认演示素材顺序。
// 清除条件只验证面板内的纯 UI，不调用应用级搜索或模型接口。
// 窄窗口断言只检查本面板能滚动，不能替代 UI-07 的全部收缩验收。
// 不根据主题颜色判断可用性，实际 disabled 与 ARIA 才是断言依据。
// 错误行保留原始名称，状态占位不会把整行变成无法识别的空白。
async function sampleFlow(ctx) {
  // voice-0 到 voice-11 是独立条目，列表超出高度后才有可测的滚动距离。
  // probing 与 unavailable 使用视频封面，但显式状态必须优先于已有图片。
  // no-cover 使用图片类型的 null 封面，不能被显示成音频波形。
  // no-cover 与 voice 分属两个实例，选中结果不能由媒体类型共用变量。
  // 单行禁用读原生 disabled，CSS 变灰并不能阻止调用 onSelect。
  // 长名检查 scrollWidth 大于 clientWidth，确保确实触发省略而非只写了样式。
  // title 应仍包含 final_revision，辅助查看不能拿到已截断的显示文本。
  // 标题 top 在列表滚动前后相等，排除整个面板在一起滚动的伪通过。
  // scrollTop 必须大于零，空列表即使 overflow:auto 也不能通过这项反证。
  // scrollWidth 不超过 clientWidth，说明长名没有造成内部横向漂移。
  const a = sample("A"), b = sample("B");
  await filter(ctx, a, 3); await search(ctx, a, "bg");
  await ctx.run(`document.querySelector('${b} [data-editor-asset=voice]').click()`); await ctx.delay(60);
  ctx.smoke.check("Media panel instances have independent filters, queries and selection", await ctx.run(`document.querySelectorAll('${a} [data-editor-asset]').length===1&&document.querySelectorAll('${b} [data-editor-asset]').length===5&&document.querySelector('${b} input').value===''&&document.querySelector('${b} [data-editor-asset=voice]').getAttribute('aria-current')==='true'`));
  await scenario(ctx, 4);
  ctx.smoke.check("Probing and invalid media are disabled but missing covers remain selectable", await ctx.run(`document.querySelector('${a} [data-editor-asset=probing]').disabled&&document.querySelector('${a} [data-editor-asset=unavailable]').disabled&&!document.querySelector('${a} [data-editor-asset=no-cover]').disabled&&!!document.querySelector('${a} [data-editor-asset=no-cover] [data-editor-placeholder=missing]')`));
  await ctx.run(`document.querySelector('${a} [data-editor-asset=no-cover]').click()`); await ctx.delay(60);
  ctx.smoke.check("A missing-cover image can be selected without changing B's audio selection", await ctx.run(`document.querySelector('${a} [data-editor-asset=no-cover]').getAttribute('aria-current')==='true'&&document.querySelector('${b} [data-editor-asset=voice]').getAttribute('aria-current')==='true'`));
  ctx.smoke.check("Long filenames ellipsize while retaining their complete title", await ctx.run(`(()=>{const e=document.querySelector('${a} [data-editor-asset=scene-01]'),s=e.querySelector('strong');return e.title.includes('final_revision')&&getComputedStyle(s).textOverflow==='ellipsis'&&s.scrollWidth>s.clientWidth})()`));
  ctx.smoke.check("Only media results scroll while media tools stay fixed", await ctx.run(`(()=>{const p=document.querySelector('${a}'),list=p.querySelector('[data-editor-media-results]'),before=p.querySelector('h2').getBoundingClientRect().top;list.scrollTop=200;return list.scrollTop>0&&p.querySelector('h2').getBoundingClientRect().top===before&&list.scrollWidth<=list.clientWidth+1})()`));
  await ctx.run(`document.querySelector('${a} [data-editor-media-results]').scrollTop=0;document.querySelector('${a}').scrollIntoView({block:'center'})`);
}

// 同一页面切主题，不重新创建实例，才能暴露主题切换时重置选择的问题。
// 主题使用原有外观菜单，不给根节点写 data-theme 作为测试捷径。
// 等待主题转场结束后关菜单，运行图不会被弹层遮挡。
// 窄视口保留样板素材栏，默认工作区的收缩策略不在 UI-03 提前改写。
// 测试最后返回原工程，确认样板选择不污染静态选中片段。
// 外层继续运行 legacy/GIF 宿主检查与渲染错误汇总。
// 两个 helper 串行共用一个窗口，不触发 Electron 单实例冲突。
// 宽屏和窄屏都保持同一份演示内容，而非替换为简化移动页面。
// 工具栏仍位于各面板顶部，窄屏整页可纵向滚动到第二实例。
// 隔离目录仅保存截图，返回不会触发项目保存或媒体导出。
// 深浅截图采用同一个选择结果，方便比较主题下的可读性。
// 波形与缩略图不做颜色反转，继承的是外壳语义色。
// 真实 Windows 缩放、遮挡与读屏不由这组 offscreen 测试冒充通过。
// 若路由没加载，wait 必须超时失败，不能截旧页面冒充素材状态页。
// 这里启用的焦点模拟属于前面的 UI-02 调试设置，不进入产品运行配置。
// UI-04–UI-08 仍需独立验收，素材回归通过不改变后续任务状态。
async function checkVideoUiMedia(ctx) {
  // 前一个 helper 已回到默认工程，这里不另 loadURL 绕过路由清理。
  // 素材样板通过实际工作栏链接打开，用户也能访问同一个状态入口。
  // 首次定位 A 后再切场景，截图不会停留在原 UI-02 字段样板顶部。
  // 深浅主题之间保持同一份 EDGE_ASSETS，比较的是颜色而非数据变化。
  // 主题转场完成条件防止截到一半深色一半浅色的动画中间帧。
  // 窄窗口宽度为 700，触发应用移动导航；不是仅改变素材栏内联宽度。
  // 回宽屏先量外壳新占位，避免把移动导航高度用于桌面布局尺寸期望。
  // 返回后断言仍是五个演示片段，样板长列表不应追加任何时间线对象。
  await mainFlow(ctx);
  await ctx.run("document.querySelector('a[href=\"/tools/video/editor/samples\"]').click()");
  await ctx.wait("document.querySelector('[data-editor-media-sample=A]')");
  await ctx.run(`document.querySelector('${sample("A")}').scrollIntoView({block:'center'})`);
  await libraryStates(ctx); await sampleFlow(ctx); await shot(ctx, "ui-03-media-samples-light");
  await ctx.run("document.querySelector('[data-theme-trigger]').click()"); await ctx.wait("document.querySelector('[data-theme-option=dark]')");
  await ctx.run("document.querySelector('[data-theme-option=dark]').click()"); await ctx.wait("document.documentElement.dataset.theme==='dark'&&!document.documentElement.classList.contains('theme-ripple')");
  await ctx.run("document.querySelector('[data-theme-trigger]').click()"); await ctx.wait("!document.getElementById('appearance-popover')");
  ctx.smoke.check("Theme switch preserves separate media selections", await ctx.run(`document.querySelector('${sample("A")} [data-editor-asset=no-cover]').getAttribute('aria-current')==='true'&&document.querySelector('${sample("B")} [data-editor-asset=voice]').getAttribute('aria-current')==='true'`));
  await shot(ctx, "ui-03-media-samples-dark");
  await ctx.win.webContents.debugger.sendCommand("Emulation.setDeviceMetricsOverride", { width: 700, height: 850, deviceScaleFactor: 1, mobile: false }); await ctx.delay(200);
  await ctx.run(`document.querySelector('${sample("A")}').scrollIntoView({block:'start'})`);
  ctx.smoke.check("Narrow media samples retain internal scroll boundaries without page overflow", await ctx.run(`(()=>{const h=document.querySelector('[data-editor-samples]'),p=document.querySelector('${sample("A")} [data-editor-region=R02]');return h.scrollWidth<=h.clientWidth+1&&p.getBoundingClientRect().width>0&&p.querySelector('[data-editor-media-results]').scrollHeight>p.querySelector('[data-editor-media-results]').clientHeight})()`));
  await shot(ctx, "ui-03-media-samples-narrow");
  await ctx.run("document.querySelector('[data-editor-samples] > a').click()"); await ctx.wait("document.querySelector('[data-video-editor-ui]')"); await ctx.win.loadURL('app://app/tools/video/editor/samples/project'); await ctx.wait("document.querySelector('[data-video-editor-ui=\"UI-04\"]')");
  await ctx.sizeHost(1600, 1000); await shot(ctx, "ui-03-media-dark");
  ctx.smoke.check("Returning from media samples retains the original project clip", await ctx.run("document.querySelector('[data-editor-clip=clip-02]').getAttribute('aria-pressed')==='true'&&document.querySelectorAll('[data-editor-clip]').length===5"));
}
module.exports = { checkVideoUiMedia };

scripts/lib/check-video-ui-preview.js:
/**
 * UI-04 预览回归沿用主套件的隔离窗口、生产桥和 app:// 静态导出。
 * 测试像切换监看器的节目单：只换片段引用，不移动素材货架上的高亮标签。
 * 图片、时间码和画布比例从真实 DOM 读取，不访问 React 内部状态。
 * 所有状态通过页面显式场景按钮进入，不直接改 CSS 或禁用属性自证。
 * 黑场、等待、失败与空态分别验证，不能用一个占位元素替代全部预期。
 * 截图来自 capturePage，既不重新生成设计图也不裁掉溢出问题。
 * 本脚本不初始化视频播放器，不读用户素材，也不创建工程文件。
 * 外层零业务计数保证点击禁用按钮不会泄漏导入、处理和播放请求。
 */
const fs = require("node:fs"), path = require("node:path");
// preview 样板与原 UI-02/UI-03 A/B 使用不同数据标记，不能跨组误匹配。
// 作用域由固定测试常量构造，不包含用户文件名或外部 URL。
// 同名素材在两个实例都有，所有定位必须先限制实例身份。
const scope = id => `[data-editor-preview-sample=${id}]`;
// 预览状态标记由公共 ProgramPreview 输出，样板本身不能伪造这份结论。
// panel 用于读取图像、时间码和返回按钮，不从其他组件猜当前预览状态。
// 状态变化保持相同面板实例，可发现图片失败记忆是否错误串到另一个实例。
const panel = id => `${scope(id)} [data-editor-region=R03]`;

// 片段按钮通过真实 onClick 改局部选中 ID，再由 ProgramPreview 映射资源。
// 按索引定位使用固定五项演示片段顺序，文件名变化不应影响身份。
// 点击之后等待 React 提交，不用直接调用预览组件或改 data 属性。
// 条件判断在调用方读取真实结果，点击完成本身不算断言通过。
async function clip(ctx, index) {
  // 固定集合包含两个视频、一个图片和两份音频，不能按类型只取第一个匹配项。
  // 每次操作都限定 A，后续 B 不变是对状态共享错误的反证。
  // 文件名只用作用户可见标签，身份切换由按钮绑定的 clip.id 决定。
  // 不从样板按钮 pressed 推断封面正确，还要读取公共预览 img 的 alt 和时间。
  // 这能发现按钮已经变色但预览仍写死 scene-02 的实现。
  // 本轮不拖动轨道内容，也不派发 pointermove 来冒充片段修剪。
  // 选择动作不会改变工程 duration，时长仍由演示项目参数给出。
  // 短暂提交等待没有自动重试；错误结果会保留到下一条断言中。
  await ctx.run(`document.querySelectorAll('${scope("A")} [data-preview-clip-choices] button')[${index}].click()`);
  await ctx.delay(60);
}
// 场景定位用内部稳定键，不依赖当前语言的长状态文案。
// broken 场景必须再等真实图片错误回落，不能把点击按钮当成缺图成功。
// 这里的短等待只处理本地状态提交，没有网络或媒体解码超时重试。
// 切 ready 是显式恢复演示输入，不声称已经修复了用户损坏文件。
async function scenario(ctx, name) {
  // 场景按钮有稳定 data 键，翻译变化不会让脚本点错“加载”或“缺图”。
  // 这与片段按钮分成两个组，不把数据来源和故障状态混在一个选择器里。
  // 切 missing 不直接传 state=missing，因此能暴露资源引用查找的实际问题。
  // 切 broken 不伪造 onError，图片坏字节应由浏览器正常尝试解码。
  // error 夹具不建立网络请求，所以测试不能声称覆盖真实超时或断网恢复。
  // ready 仍复用相同组件实例，不通过重新挂载清掉错误来掩盖状态管理缺陷。
  // 如果正常封面恢复失败，后续 naturalWidth 等待会明确超时，不继续截旧图。
  // 场景切换是演示页的显式行为，产品默认工作区不出现这组按钮。
  await ctx.run(`document.querySelector('${scope("A")} [data-preview-scenario=${name}] button').click()`);
  await ctx.delay(60);
}
// 有限合成等待避免截图取得上一帧主题转场或场景切换的像素。
// 文件名由测试提供且只写隔离目录，不覆盖用户图片或设计基准。
// 图片写入成功不抵消之前的断言失败，最终结果仍归外层 harness。
// 截图保留窗口真实尺寸与宿主导航，不放大缩小来伪造断点验收。
async function shot(ctx, name) {
  // 默认图与样板图使用不同文件名，交付时能区分工程与故障演示。
  // A/B 样板的画布比例不同，截图必须保留两列，不能只截正常的 A。
  // 失败时输出仍保留，人工可以核对哪个实例或状态没有正确回落。
  // 页面滚动位置由调用方决定，本函数不偷偷滚到默认画面来让截图好看。
  // 写 PNG 属于测试产物，不是节目帧导出，不能算业务导出接通。
  // 不执行图片缩放或滤镜，运行像素直接反映实际主题与状态外观。
  await ctx.delay(200);
  fs.writeFileSync(path.join(ctx.root, `${name}.png`), (await ctx.win.webContents.capturePage()).toPNG());
}
// 主题使用应用真实外观菜单，不给根元素加 .dark 或手工改色值。
// 等转场结束后关菜单，再观察同一个预览实例的参数和错误状态。
// mode 限于内部 light/dark 常量，不接受用户输入作为 CSS 或脚本。
// 媒体内容不随主题换资源，画布也不对封面加反色滤镜。
// 等待由外层主进程计时兜底，隐藏窗口仍可结束。
// 本函数不重载页面，不能靠卸载实例掩盖主题切换导致的状态丢失。
// 菜单关闭也有明确条件，截图不能拿着遮住画面的菜单声称完整验收。
async function theme(ctx, mode) {
  // 这里等待 data-theme 是原有主题决议的结果，不直接修改该属性。
  // 前一主题菜单必须已关闭，否则第一次 click 会关闭它而不是打开新菜单。
  // 选项出现由 wait 判断，不依赖假设菜单动画永远在固定毫秒内结束。
  // 动画结束后再保存像素，避免把转场掩膜边界误当成布局错误。
  // 状态保持由后续片段 ID 和帧尾断言验证，主题开关完成不算独立性证明。
  // 主题改变不应把 B 的 24fps 改回 A 的 30fps。
  // 这组检查没有读系统缩放设置，100% CSS 视口不能冒充多 DPR 验证。
  // 用户真实偏好不受影响，菜单只写本测试隔离游客数据。
  await ctx.run("document.querySelector('[data-theme-trigger]').click()");
  await ctx.wait(`document.querySelector('[data-theme-option=${mode}]')`);
  await ctx.run(`document.querySelector('[data-theme-option=${mode}]').click()`);
  await ctx.wait(`document.documentElement.dataset.theme==='${mode}'&&!document.documentElement.classList.contains('theme-ripple')`);
  await ctx.run("document.querySelector('[data-theme-trigger]').click()");
  await ctx.wait("!document.getElementById('appearance-popover')");
}

// 两实例默认都选 clip-02，但 B 使用竖屏 24fps 与四分之一秒帧尾。
// 读取画布矩形比值，能发现 CSS 写了 aspect-ratio 却实际被父层拉伸的错误。
// A 选 clip-01 应显示 scene-01 封面和两秒工程位置，不能沿用 scene-02。
// B 继续保持 clip-02、12 秒 06 帧，证明参数与选择没有串状态。
// 随后选 A 的素材背景，节目仍必须显示 clip-01，不能拿素材选择代替片段。
// A 选图片片段后素材高亮仍是前一步背景，此处继续检查 B 原状态不受影响。
// 音频片段没有画面应有明确提示，不回退成上一次视频封面。
// 片段总数仍为五项，样板选择不是向主工程追加片段。
// program 时间展示工程位置，图片片段 20 秒起点加两秒应为 22 秒。
// selectedClip 与 selectedAsset 的变化从 ARIA 读取，不信任内部变量名称。
// 所有验证通过相同 ProgramPreview 的实际参数，默认页面也使用该公共实现。
// 音频提示不代表音频文件缺失；data 状态应是 audio 而不是 missing/error。
// 不检查媒体文件磁盘存在，因为本轮输入只有固定随包封面。
// 这组不验证时间轴剪辑命令，正式时间轴仍保持只读 clip-02。
// 两个实例虽共用静态资源，选择和失败缓存仍必须彼此隔离。
// 图片采用 contain，竖屏 B 不应该裁掉横向源封面两侧。
// 全部时间码都是暂停样例，没有通过计时器制造假播放进度。
async function mapping(ctx) {
  // A 初始 clip-02 在十秒开始，选 clip-01 后当前工程时间应回到两秒。
  // 不靠预览 img 节点引用判断切换，节点可复用但 src/alt 必须体现新素材。
  // 素材背景行被选中后，A 仍应引用 clip-01，而非自动选入 clip-bg。
  // 图片片段时间取 20+2=22 秒，不把图片 duration=null 当成零秒节目。
  // B 的素材高亮继续为 scene-02，A 的素材选择不能污染另一个实例。
  // 音频没有封面时必须卸载 img，防止上一次视频画面残留在底层。
  // 同时读音频提示文字，不能只靠隐藏图片就声称音频状态可理解。
  // 横屏与竖屏的比例容差小于百分之一，允许布局小数像素舍入。
  // ratio 从 frame 而不是整个中性 surface 读取，外层留边本就不是项目画布。
  // 帧尾检查 06 能发现把 24fps 当作毫秒或写死 30fps 的错误。
  ctx.smoke.check("Preview maps project ratios and 24fps frame tails from parameters", await ctx.run(`(()=>{const a=document.querySelector('${panel("A")} [data-editor-preview-frame]').getBoundingClientRect(),b=document.querySelector('${panel("B")} [data-editor-preview-frame]').getBoundingClientRect();return Math.abs(a.width/a.height-16/9)<.01&&Math.abs(b.width/b.height-9/16)<.01&&document.querySelector('${panel("B")} b').textContent==='00:00:12:06'})()`));
  await clip(ctx, 0);
  ctx.smoke.check("Selected video clip maps to its own cover and project time without changing B", await ctx.run(`document.querySelector('${panel("A")} img').alt.includes('scene_01.mp4')&&document.querySelector('${panel("A")} b').textContent==='00:00:02:00'&&document.querySelector('${panel("B")}').dataset.editorPreviewClip==='clip-02'`));
  await ctx.run(`document.querySelector('${scope("A")} [data-editor-asset=background]').click()`); await ctx.delay(60);
  ctx.smoke.check("Selecting a source asset never replaces the selected preview clip", await ctx.run(`document.querySelector('${scope("A")} [data-editor-asset=background]').getAttribute('aria-current')==='true'&&document.querySelector('${panel("A")}').dataset.editorPreviewClip==='clip-01'&&document.querySelector('${panel("A")} img').alt.includes('scene_01.mp4')`));
  await clip(ctx, 2);
  ctx.smoke.check("Image clip maps cover and project position without changing source selection", await ctx.run(`document.querySelector('${panel("A")} img').alt.includes('bg_01.png')&&document.querySelector('${panel("A")} b').textContent==='00:00:22:00'&&document.querySelector('${scope("B")} [data-editor-asset=scene-02]').getAttribute('aria-current')==='true'`));
  await clip(ctx, 3);
  ctx.smoke.check("Audio selection shows a clear no-picture state instead of a stale video", await ctx.run(`document.querySelector('${panel("A")}').dataset.editorPreviewState==='audio'&&!document.querySelector('${panel("A")} img')&&document.querySelector('${panel("A")}').textContent.includes('音频片段没有画面')`));
  await clip(ctx, 1);
}

// 同一预览实例连续切换状态，工具栏位置不应随着反馈文字长度变化。
// empty 清空片段参数，所以当前时间应归零，但项目总时长仍为 30 秒。
// missing 场景传未知 assetId，测试覆盖实际引用查找失败。
// loading 不能残留旧图片，且整个面板必须标记 busy。
// error 使用公共 alert，不能只让缩略图角落变红而没有文字原因。
// black 是明确黑场，不能把它标记为等待或永久缺图。
// B 保持正常静态画面，A 的状态不能覆盖另一台预览。
// broken 用坏字节让浏览器实际触发 onError，等待条件不派发假 error 事件。
// 换回正常封面后应恢复 ready，不能让失败记忆永久污染当前预览实例。
// 样板没有播放/导出回调，状态恢复只说明显示参数有效。
// 禁用按钮仍可保留提示，不允许禁用只是视觉灰色而实际发出处理请求。
// 长名在下一组另测，异常反馈与文件名截断不能互相代替。
// 记录控制栏 top 后逐状态比较，直接发现占位撑高画布挤走控制条的问题。
// 默认源图与场景资源均随包提供，本组无需外部网络稳定性作为前提。
// loading 的旋转关闭不影响文字提示，本轮未声明完成 reduced-motion 全套测量。
// 错误场景截图保留 B 正常画面，便于人工对比隔离与占位层级。
// 不在错误后提供空函数重试按钮，避免制造假修复交互。
// 所有 data 状态必须来自 ProgramPreview，不能仅按样板选中了哪个按钮判定。
// 没有片段时仍保留标题和控制栏，空态不能让节目面板高度塌陷。
// 场景切换不会写正式工程，离开页后默认 clip-02 继续不变。
async function states(ctx) {
  // error 的角色必须是 alert，只有 data 状态正确却没有可读反馈不能通过。
  // empty 的当前时间检查归零，防止无片段时还保留之前节目的十二秒。
  // 两个补充判据仍在同一状态循环里，不能切到另一个页面再验证正常样例。
  // 加载条件检查实际 busy 属性，错误场景不应借用 busy 持续冒充等待。
  // 占位语义来自公共 EditorPlaceholder，测试不替产品写额外 alert 节点。
  // top 在正常画面时记录，之后空态与错误都必须留在同一控制条位置。
  // 占位标题再长也不应把按钮推到面板之外，这是固定三行布局的实际边界。
  // 每个状态都检查 A 没有 img，等待/失败不能把旧图留给用户误读。
  // B 的状态为 ready，与 A 五种状态逐一比较，而非仅在循环结束后比较一次。
  // 循环不重新进入路由，所以一轮状态留下的错误属性可能被下一轮检测到。
  // broken 后等待 missing，读取的是公共面板的状态优先级结果。
  // 同时检查 B 仍有图片，可发现错误缓存被写成模块级共享变量。
  // 恢复 ready 后等待 naturalWidth 大于零，不能只凭 img 节点出现断言有效。
  // error 截图的文字来自独立翻译键，不用浏览器自带破图标满足异常展示。
  // 状态夹具本身不取消或修复文件，只控制当前静态预览的输入。
  const top = await ctx.run(`document.querySelector('${panel("A")} > div:last-child').getBoundingClientRect().top`);
  for (const state of ["empty", "loading", "missing", "error", "black"]) {
    await scenario(ctx, state);
    ctx.smoke.check(`Program ${state} state is explicit and preserves its transport boundary`, await ctx.run(`(()=>{const p=document.querySelector('${panel("A")}');return p.dataset.editorPreviewState==='${state}'&&!p.querySelector('img')&&Math.abs(p.lastElementChild.getBoundingClientRect().top-${top})<1&&document.querySelector('${panel("B")}').dataset.editorPreviewState==='ready'&&(${JSON.stringify(state)}!=='loading'||p.getAttribute('aria-busy')==='true')&&(${JSON.stringify(state)}!=='error'||!!p.querySelector('[role=alert]'))&&(${JSON.stringify(state)}!=='empty'||p.querySelector('b').textContent==='00:00:00:00')})()`));
  }
  await scenario(ctx, "error"); await shot(ctx, "ui-04-preview-error-dark");
  await scenario(ctx, "broken"); await ctx.wait(`document.querySelector('${panel("A")}').dataset.editorPreviewState==='missing'&&!document.querySelector('${panel("A")} img')`);
  ctx.smoke.check("Actual cover decoding failure falls back only in its own preview", await ctx.run(`!!document.querySelector('${panel("A")} [data-editor-placeholder=missing]')&&!!document.querySelector('${panel("B")} img')`));
  await scenario(ctx, "ready"); await ctx.wait(`document.querySelector('${panel("A")} img')?.naturalWidth>0`);
  ctx.smoke.check("A new valid cover recovers from the previous failed URL", await ctx.run(`document.querySelector('${panel("A")}').dataset.editorPreviewState==='ready'`));
}

// source 与 program 复用同一容器，进入素材查看后有明确返回入口。
// source 的两秒是片段局部时间，返回 program 后应恢复到 12 秒工程时间。
// 返回操作不得改变片段 ID、素材高亮或 B 的查看模式。
// 长名必须在标题行省略，完整 title 保留用于查看，而不是强迫标题换行。
// 按钮原因通过 aria-describedby 取实际节点，验证专属静态边界提示已接入。
// 五个走带动作都要原生禁用，不能只检查播放一个按钮。
// 禁用操作点击后外层统计仍为零，这里不自行重置业务计数掩盖副作用。
// 键盘通过原生 Enter 激活 source 开关，不直接调用组件方法。
// 先聚焦正确按钮，焦点圈须实际可见，不能只断言 DOM 可以 focus。
// 切模式不会开启隐藏 video/audio 标签，当前仍是静态图像查看。
// 样板 source 返回保持当前长名称场景，证明不是重载页面恢复默认状态。
// 同一实例返回后时间码改变来自模式参数，而不是时钟走了十秒。
// 真实 seek 不在本轮范围，不向拖动播放头注入任何事件。
// 对标题宽度的检查在真实样板列完成，后续窄屏再核对没有横向整页溢出。
// 此处检查完整 title 含 final_revision，不能只验证 text-overflow 样式存在。
// 如果文字没有发生实际溢出，长名样例不能通过这项省略反证。
// 时间码仍使用 30fps，B 竖屏 24fps 的参数不会串入 A。
// source 的总长来自片段 end-start=8，不误用 30 秒工程时长。
async function sourceMode(ctx) {
  // 名称夹具刻意长于宽列可用空间，以便验证实际省略，而非仅验证 CSS 声明。
  // 文件全名仍保留 .mp4，不能截掉数据再拿截断名称作为 title。
  // source 开关位于状态组末尾，返回按钮则在公共预览标题栏中。
  // 两个操作路径不同，可以发现按钮图标存在却遗漏 onBack 绑定的问题。
  // onBack 不重建 ProgramPreview，状态长名和素材背景选择应继续保留。
  // source 时间分母是八秒片段长度，不能继续显示工程总长三十秒。
  // 返回后工程时间恢复十二秒，不把局部两秒写回工程位置。
  // 五个按钮包括适应，不能因为它看似纯 UI 就误开启尚无实现的缩放动作。
  // 本组主动点击每个禁用按钮，外层业务计数能观察是否发生意外请求。
  // 全部原因节点必须存在且包含静态预览说明，title 有文字不代表读屏描述正确。
  await scenario(ctx, "long");
  ctx.smoke.check("Long preview names ellipsize and preserve their full title", await ctx.run(`(()=>{const s=document.querySelector('${panel("A")} header > span:last-child');return s.title.includes('final_revision')&&getComputedStyle(s).textOverflow==='ellipsis'&&s.scrollWidth>s.clientWidth})()`));
  await ctx.run(`document.querySelector('${scope("A")} [data-preview-state-choices] > span:last-child button').focus()`);
  ctx.win.webContents.sendInputEvent({ type: "keyDown", keyCode: "Enter" }); ctx.win.webContents.sendInputEvent({ type: "char", keyCode: "\r" }); ctx.win.webContents.sendInputEvent({ type: "keyUp", keyCode: "Enter" });
  await ctx.wait(`document.querySelector('${panel("A")}').dataset.editorPreviewMode==='source'`);
  ctx.smoke.check("Source view has a title, return action and local clip time", await ctx.run(`document.querySelector('${panel("A")} h2').textContent==='素材查看'&&document.querySelector('${panel("A")} b').textContent==='00:00:02:00'&&document.querySelector('${panel("A")} > div:last-child').textContent.includes('00:00:08:00')&&document.querySelector('${panel("B")}').dataset.editorPreviewMode==='program'&&parseFloat(getComputedStyle(document.activeElement).outlineWidth)>=2`));
  await ctx.run(`document.querySelector('${panel("A")} header button').click()`); await ctx.delay(60);
  ctx.smoke.check("Returning restores program time without changing clip or asset selection", await ctx.run(`document.querySelector('${panel("A")}').dataset.editorPreviewMode==='program'&&document.querySelector('${panel("A")} b').textContent==='00:00:12:00'&&document.querySelector('${panel("A")}').dataset.editorPreviewClip==='clip-02'&&document.querySelector('${scope("A")} [data-editor-asset=background]').getAttribute('aria-current')==='true'`));
  ctx.smoke.check("All preview processing controls stay disabled with an accurate reason", await ctx.run(`(()=>{const buttons=[...document.querySelectorAll('${panel("A")} > div:last-child button')];buttons.forEach(b=>b.click());return buttons.length===5&&buttons.every(b=>b.disabled&&document.getElementById(b.getAttribute('aria-describedby')).textContent.includes('静态预览'))&&!document.querySelector('${panel("A")} video,${panel("A")} audio')})()`));
}

// 外层先验过素材区，这里进入新增节目样板，不重复造窗口或游客桥。
// 默认预览也截深色图，证明参数化没有改变主工作区的单节目布局。
// 样板引用通过现有组件预览入口到达，不创建只有测试才能打开的路由。
// 截图前把 A/B 带入视口，避免停在上一组素材样板的位置截错内容。
// 浅深主题切换保持长名称场景与选中，不能重建简单页面掩盖状态丢失。
// 窄窗口验证实际 700px 浏览器视口，应用移动导航仍可用。
// 预览控制栏允许自己的横向滚动，但页面不能被长标题撑宽。
// 画布与比例框都必须位于预览内部，不能靠父 overflow 隐藏越界内容。
// 结束通过原返回链接回默认工程，时间线仍应只选 clip-02。
// 主时间轴没有被启用，样板可选片段不代表 UI-06 交互已完成。
// 同一个 Electron 实例按顺序执行，各 helper 不并行竞争路由或主题。
// 未跑真实 Windows DPR、遮挡或读屏软件，不能由截图推断这些维度通过。
// 运行图包括宿主导航与窗口控制，不裁成概念图冒充整个程序状态。
// 回宽屏先让原 sizeHost 校准真实外壳占位，不拼旧导航宽度常量。
// 断言失败仍保留临时输出，最终退出由外层 harness 决定。
// 无视频音频元素是重要边界，但不替代外层 IPC 调用计数检查。
async function checkVideoUiPreview(ctx) {
  // 此时上一素材 helper 已恢复深色默认工程，首张图应为同一默认节目状态。
  // 预览样板在页面后部，显式 scrollIntoView 避免截到上一个素材分组。
  // A/B 外框共享 sampleGrid，改窄窗口后应只重排而不改变片段参数。
  // narrow 检查 frame 四边，防止仅看 scrollWidth 而遗漏纵向裁切。
  // 默认预览面板总数必须为一，样板节点不能永久隐藏在工作区里。
  // 返回时 clip-02 的边框仍在，A 的选择没有写入主时间轴状态。
  // helper 结束后旧视频/GIF 宿主还会被外层回归，保证局部样式不泄漏。
  // 后续 UI-05–UI-08 保持待办，测试通过只证明本次静态预览契约。
  await shot(ctx, "ui-04-default-dark");
  await ctx.run("document.querySelector('a[href=\"/tools/video/editor/samples\"]').click()"); await ctx.wait("document.querySelector('[data-editor-preview-sample=A]')");
  await ctx.run(`document.querySelector('${scope("A")}').scrollIntoView({block:'start'})`);
  await mapping(ctx); await states(ctx); await sourceMode(ctx); await shot(ctx, "ui-04-preview-samples-dark");
  await theme(ctx, "light");
  ctx.smoke.check("Theme switch preserves preview and source selection in both instances", await ctx.run(`document.querySelector('${panel("A")}').dataset.editorPreviewClip==='clip-02'&&document.querySelector('${scope("A")} [data-editor-asset=background]').getAttribute('aria-current')==='true'&&document.querySelector('${panel("B")} b').textContent==='00:00:12:06'&&getComputedStyle(document.querySelector('${panel("B")} img')).filter==='none'`));
  await shot(ctx, "ui-04-preview-samples-light");
  await ctx.win.webContents.debugger.sendCommand("Emulation.setDeviceMetricsOverride", { width: 700, height: 900, deviceScaleFactor: 1, mobile: false }); await ctx.delay(200);
  await ctx.run(`document.querySelector('${scope("A")}').scrollIntoView({block:'start'})`);
  ctx.smoke.check("Narrow preview keeps its canvas, long title and transport within the panel", await ctx.run(`(()=>{const h=document.querySelector('[data-editor-samples]'),p=document.querySelector('${panel("A")}'),s=p.querySelector('[data-editor-preview-surface]').getBoundingClientRect(),f=p.querySelector('[data-editor-preview-frame]').getBoundingClientRect();return h.scrollWidth<=h.clientWidth+1&&f.width>0&&f.left>=s.left-1&&f.right<=s.right+1&&f.top>=s.top-1&&f.bottom<=s.bottom+1&&Math.abs(f.width/f.height-16/9)<.01&&p.lastElementChild.getBoundingClientRect().bottom<=p.getBoundingClientRect().bottom+1})()`));
  await shot(ctx, "ui-04-preview-samples-narrow");
  await ctx.run("document.querySelector('[data-editor-samples] > a').click()"); await ctx.wait("document.querySelector('[data-video-editor-ui]')"); await ctx.win.loadURL('app://app/tools/video/editor/samples/project'); await ctx.wait("document.querySelector('[data-video-editor-ui=\"UI-04\"]')"); await ctx.sizeHost(1600, 1000);
  ctx.smoke.check("Leaving preview samples restores the default project mapping", await ctx.run("document.querySelector('[data-video-editor-ui] [data-editor-region=R03]').dataset.editorPreviewClip==='clip-02'&&document.querySelector('[data-editor-clip=clip-02]').getAttribute('aria-pressed')==='true'&&document.querySelectorAll('[data-video-editor-ui] [data-editor-region=R03]').length===1"));
  await shot(ctx, "ui-04-default-light");
}
// UI-07也通过同一主题菜单切换，导出已有测试机制，避免两处维护不同点击顺序。
// 此导出只给测试helper复用，不添加到产品window或preload能力里。
// 主题状态仍由生产themeSignals决议，helper不能直接改data-theme自证。
module.exports = { checkVideoUiPreview, setVideoUiTheme: theme };

